import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界: z.object({
    当前位置: z.string(),
    时间: z.string(),
    大事件: z.string(),
  }),

  主角: z.object({
    姓名: z.string(),
    性别: z.string(),
    身份: z.string(),
    种族: z.string(),
    所属势力: z.string(),
    当前状态: z.string(),
    是否为阴阳师: z.boolean(),
    是否为游戏模式: z.boolean(),
    召唤符咒数量: z.coerce.number(),
    技能: z.record(
      z.string().describe('技能名称'),
      z.object({
        描述: z.string(),
      }).prefault({})
    ),
    持有物品: z.record(
      z.string().describe('物品名称'),
      z.object({
        类型: z.string(),
        数量: z.coerce.number(),
        作用: z.string(),
        品阶: z.string(),
      }).prefault({})
    ).transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0)),
  }),

  式神录: z.record(
    z.string().describe('式神名称'),
    z.object({
      性别: z.string(),
      种族: z.string(),
      描述: z.string(),
      外表: z.string(),
      忠诚度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
      好感度: z.coerce.number().transform(v => _.clamp(v, -100, 100)),
      技能: z.record(
        z.string().describe('技能名称'),
        z.object({
          描述: z.string(),
        }).prefault({})
      ).prefault({}),
      稀有度: z.enum(['N', 'R', 'SR', 'SSR', '']),
      星级: z.coerce.number().transform(v => _.clamp(v, 2, 6)),
      等级: z.coerce.number().transform(v => _.clamp(v, 1, 40)),
      当前经验值: z.coerce.number(),
      升级所需经验值: z.coerce.number(),
    }).prefault({})
  ).transform(data => {
    _.forEach(data, (shikigami) => {
      // 等级上限由星级决定: 2星20级，每多1星上限+5，最高40级
      const maxLevel = _.clamp(10 + shikigami.星级 * 5, 20, 40);

      const getRequiredExp = (nextLevel) => {
        const x = nextLevel;
        if (x % 2 !== 0) {
          return 2.5 * Math.pow(x, 3) + 25 * Math.pow(x, 2) - 12.5 * x + 165;
        } else {
          return 2.5 * Math.pow(x, 3) + 22.5 * Math.pow(x, 2) - 10 * x + 150;
        }
      };

      // 处理自动升级逻辑
      while (shikigami.等级 < maxLevel) {
        const reqExp = getRequiredExp(shikigami.等级 + 1);
        if (shikigami.当前经验值 >= reqExp) {
          shikigami.当前经验值 -= reqExp;
          shikigami.等级 += 1;
        } else {
          break;
        }
      }

      // 更新当前等级下的升级所需经验值
      if (shikigami.等级 >= maxLevel) {
        shikigami.等级 = maxLevel;
        shikigami.当前经验值 = 0;
        shikigami.升级所需经验值 = 0;
      } else {
        shikigami.升级所需经验值 = getRequiredExp(shikigami.等级 + 1);
      }
    });
    return data;
  }),

  人际关系: z.record(
    z.string().describe('人物姓名'),
    z.object({
      性别: z.string(),
      身份: z.string(),
      所属势力: z.string(),
      种族: z.string(),
      当前状态: z.string(),
      性格: z.string(),
      是否在场: z.boolean(),
      内心想法: z.string(),
      好感度: z.coerce.number().transform(v => _.clamp(v, -100, 100)),
    }).prefault({})
  ),

  势力关系: z.record(
    z.string().describe('势力名称'),
    z.object({
      好感度: z.coerce.number().transform(v => _.clamp(v, -100, 100)),
      声望值: z.coerce.number(),
    }).prefault({})
  )
});

$(() => {
  registerMvuSchema(Schema);
})

$(() => {
  appendInexistentScriptButtons([{ name: '打开地图', visible: true }]);

  eventOn(getButtonEvent('打开地图'), errorCatched(async () => {
    // 获取最新的 AI 楼层
    const lastId = getLastMessageId();
    const messages = getChatMessages(`0-${lastId}`, { role: 'assistant' });

    if (messages.length === 0) {
      toastr.warning('没有找到 AI 消息楼层');
      return;
    }

    const latestAssistant = messages[messages.length - 1];
    const messageId = latestAssistant.message_id;

    // 在消息末尾追加 <map> 标签
    const newMessage = latestAssistant.message + '\n<map>';
    await setChatMessages([{ message_id: messageId, message: newMessage }]);

    toastr.success(`已在第 ${messageId} 楼插入 <map> 标签`);
  }));
});

$(() => {
  appendInexistentScriptButtons([
    { name: '打开地图', visible: true },
    { name: '式神召唤', visible: true }
  ]);

  eventOn(getButtonEvent('打开地图'), errorCatched(async () => {
    const lastId = getLastMessageId();
    const messages = getChatMessages(`0-${lastId}`, { role: 'assistant' });

    if (messages.length === 0) {
      toastr.warning('没有找到 AI 消息楼层');
      return;
    }

    const latestAssistant = messages[messages.length - 1];
    const messageId = latestAssistant.message_id;

    const newMessage = latestAssistant.message + '\n<map>';
    await setChatMessages([{ message_id: messageId, message: newMessage }]);

    toastr.success(`已在第 ${messageId} 楼插入 <map> 标签`);
  }));


  eventOn(getButtonEvent('式神召唤'), errorCatched(async () => {

    await waitGlobalInitialized('Mvu');


    const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });


    const isGameMode = _.get(mvuData, 'stat_data.是否为游戏模式') === true ||
                       _.get(mvuData, 'stat_data.主角.是否为游戏模式') === true;

    if (!isGameMode) {
      toastr.warning('当前为非游戏模式，无法使用此功能');
      return;
    }

    const lastMsg = getChatMessages(-1)[0];
    if (!lastMsg) {
      toastr.warning('没有找到消息楼层');
      return;
    }

    const newMessage = lastMsg.message + '\n<召唤>';
    await setChatMessages([{ message_id: lastMsg.message_id, message: newMessage }]);

    toastr.success(`已在第 ${lastMsg.message_id} 楼插入 <召唤> 标签`);
  }));
});

