    const vv = hostWindow.visualViewport;
    return vv ? vv.height : hostWindow.innerHeight;
  }

  function defaultFabPos() {
    const vw = hostWindow.innerWidth;
    const vh = hostWindow.innerHeight;
    return { x: vw - FAB_SIZE - 16, y: Math.floor(vh * 0.38) };
  }

  function clampPos(x, y) {
    const vw = hostWindow.innerWidth;
    const vh = hostWindow.innerHeight;
    return {
      x: clampVal(x, EDGE_GAP, Math.max(EDGE_GAP, vw - FAB_SIZE - EDGE_GAP)),
      y: clampVal(y, EDGE_GAP, Math.max(EDGE_GAP, vh - FAB_SIZE - EDGE_GAP))
    };
  }

  function readFabPos() {
    try {
      const raw = hostWindow.localStorage.getItem(STORAGE_KEY_POS);
      if (raw) {
