        return clampPos(parsed.x, parsed.y);
      }
    } catch (e) {}
    return defaultFabPos();
  }

  function saveFabPos(pos) {
    try {
      hostWindow.localStorage.setItem(STORAGE_KEY_POS, JSON.stringify(pos));
