      console.log('[OnmyojiBgm] 侧边智能停靠播放器初始化就绪。');
    },

    // 智能计算面板坐标：PC 端紧贴 FAB 侧边，绝不出现在屏幕中心
    updateLayout() {
      const isMobile = hostWindow.innerWidth <= 768;
      const safeVh = getSafeViewportHeight();
      const safeVw = hostWindow.innerWidth;

      if (isMobile) {
        domPanel.classList.add('mobile');
        domSwipeHint.style.display = 'flex';
        domMobileCloseBar.style.display = 'flex';

        const panelHeight = Math.floor(safeVh * 0.86);
        const topPos = safeVh - panelHeight;

        domPanel.style.left = '0px';
        domPanel.style.top = `${topPos}px`;
        domPanel.style.width = '100vw';
        domPanel.style.height = `${panelHeight}px`;
      } else {
        domPanel.classList.remove('mobile');
        domSwipeHint.style.display = 'none';
        domMobileCloseBar.style.display = 'none';

        const panelW = 340;
        const panelH = Math.min(500, Math.floor(safeVh * 0.75));

        // 智能锚定计算：默认放置在 FAB 左侧
        let targetLeft = state.fabPos.x - panelW - 10;
        // 如果悬浮球太靠左，则面板放在 FAB 右侧
        if (targetLeft < EDGE_GAP) {
          targetLeft = state.fabPos.x + FAB_SIZE + 10;
        }

        // 垂直对齐计算：尽量与 FAB 垂直居中对齐，并做视口边界 clamp
        let targetTop = state.fabPos.y - Math.floor(panelH / 2) + Math.floor(FAB_SIZE / 2);
        targetTop = clampVal(targetTop, EDGE_GAP, safeVh - panelH - EDGE_GAP);
        targetLeft = clampVal(targetLeft, EDGE_GAP, safeVw - panelW - EDGE_GAP);

        domPanel.style.left = `${targetLeft}px`;
        domPanel.style.top = `${targetTop}px`;
        domPanel.style.width = `${panelW}px`;
        domPanel.style.height = `${panelH}px`;
      }

      this.setFabPos(state.fabPos.x, state.fabPos.y);
    },

    setFabPos(x, y) {
      const clamped = clampPos(x, y);
      state.fabPos.x = clamped.x;
      state.fabPos.y = clamped.y;
      domFab.style.left = `${clamped.x}px`;
      domFab.style.top = `${clamped.y}px`;
      saveFabPos(clamped);

      // 如果面板处于打开状态，同步更新跟随位置
      if (state.isPanelOpen && hostWindow.innerWidth > 768) {
        const safeVh = getSafeViewportHeight();
        const safeVw = hostWindow.innerWidth;
        const panelW = 340;
        const panelH = Math.min(500, Math.floor(safeVh * 0.75));

        let targetLeft = clamped.x - panelW - 10;
        if (targetLeft < EDGE_GAP) {
          targetLeft = clamped.x + FAB_SIZE + 10;
        }
        let targetTop = clamped.y - Math.floor(panelH / 2) + Math.floor(FAB_SIZE / 2);
        targetTop = clampVal(targetTop, EDGE_GAP, safeVh - panelH - EDGE_GAP);
        targetLeft = clampVal(targetLeft, EDGE_GAP, safeVw - panelW - EDGE_GAP);

        domPanel.style.left = `${targetLeft}px`;
        domPanel.style.top = `${targetTop}px`;
      }
    },

    resetPosition() {
      const pos = defaultFabPos();
      this.setFabPos(pos.x, pos.y);
      this.openPanel();
    },

    renderList() {
      const activeList = getActiveList();
      domListBox.innerHTML = '';

      if (activeList.length === 0) {
        domListBox.innerHTML = '<div class="onm-empty-hint">暂无收藏曲目，点击曲目右侧 ❤️ 即可添加</div>';
        return;
      }

      activeList.forEach((track, i) => {
        const isFav = state.favIds.includes(track.id);
        const item = hostDoc.createElement('div');
        item.className = `onm-item ${i === state.currentIndex ? 'active' : ''}`;
        item.innerHTML = `
          <div class="onm-item-info">
            <span>${i + 1}.</span>
            <span class="onm-item-title">${track.title}</span>
            <span class="onm-item-cat">${track.category || '平安京'}</span>
          </div>
          <button class="onm-item-fav-btn" title="${isFav ? '取消收藏' : '加入收藏'}">${isFav ? '❤️' : '🤍'}</button>
        `;

        item.onclick = (e) => {
          if (e.target.classList.contains('onm-item-fav-btn')) return;
          this.playTrack(i);
        };

        const favBtn = item.querySelector('.onm-item-fav-btn');
        favBtn.onclick = (e) => {
          e.stopPropagation();
          this.toggleFavorite(track.id);
        };

        domListBox.appendChild(item);
      });
    },

    updateView(index, playing) {
      const activeList = getActiveList();
      if (activeList.length === 0) {
        domTitle.innerText = '暂无可播曲目';
        domCat.innerText = '✦ 请切换歌单或添加收藏';
        domStatus.innerText = '已停歇';
        domPlay.innerText = '▶';
        domBtnFavMain.innerText = '🤍';
        return;
      }

      if (index >= activeList.length) index = 0;
      const track = activeList[index];
      if (!track) return;

      domTitle.innerText = track.title;
      domCat.innerText = `✦ ${track.category || '平安百物语'}`;
      domStatus.innerText = playing ? '雅乐流转中' : '已暂歇';
      domPlay.innerText = playing ? '⏸' : '▶';

      const isFav = state.favIds.includes(track.id);
      domBtnFavMain.innerText = isFav ? '❤️' : '🤍';

      if (track.cover) {
        domCoverImg.src = track.cover;
      }

      if (playing) {
        domFab.classList.add('playing');
        domPanel.classList.add('playing');
      } else {
        domFab.classList.remove('playing');
        domPanel.classList.remove('playing');
      }

      const items = domListBox.querySelectorAll('.onm-item');
      items.forEach((el, idx) => {
        if (idx === index) el.classList.add('active');
        else el.classList.remove('active');
      });
    },

    toggleFavorite(songId) {
      const idx = state.favIds.indexOf(songId);
      if (idx > -1) {
        state.favIds.splice(idx, 1);
      } else {
        state.favIds.push(songId);
      }
      saveFavorites(state.favIds);
      domFavCount.innerText = state.favIds.length;

      if (state.viewMode === 'fav') {
        const activeList = getActiveList();
        if (state.currentIndex >= activeList.length) {
          state.currentIndex = Math.max(0, activeList.length - 1);
        }
      }
      this.renderList();
      this.updateView(state.currentIndex, state.isPlaying);
    },

    switchView(mode) {
      if (state.viewMode === mode) return;
      state.viewMode = mode;
      state.currentIndex = 0;

      if (mode === 'all') {
        domTabAll.classList.add('active');
        domTabFav.classList.remove('active');
      } else {
        domTabFav.classList.add('active');
        domTabAll.classList.remove('active');
      }

      this.renderList();
      const activeList = getActiveList();
      if (activeList.length > 0) {
        this.playTrack(0);
      } else {
        this.pause();
        this.updateView(0, false);
      }
    },

    playTrack(targetIndex) {
      const activeList = getActiveList();
      if (activeList.length === 0) return;

      if (targetIndex < 0 || targetIndex >= activeList.length) {
        targetIndex = 0;
      }
      state.currentIndex = targetIndex;
      state.isPlaying = true;
      const track = activeList[targetIndex];

      audio.src = track.url;
      audio.currentTime = 0;
      audio.volume = state.isMuted ? 0 : state.volume / 100;
      audio.load();
      audio.play().catch((err) => {
        console.warn('[OnmyojiBgm] 待交互发声:', err);
      });

      this.updateView(targetIndex, true);
    },

    pause() {
      state.isPlaying = false;
      audio.pause();
      this.updateView(state.currentIndex, false);
    },

    togglePlay() {
      const activeList = getActiveList();
      if (activeList.length === 0) return;

      if (state.isPlaying) {
        this.pause();
      } else {
        if (audio.src && audio.currentTime > 0) {
          audio.play().catch(() => {});
          state.isPlaying = true;
          this.updateView(state.currentIndex, true);
        } else {
          this.playTrack(state.currentIndex);
        }
      }
    },

    seekPercent(pct) {
      pct = clampVal(pct, 0, 1);
      if (audio.duration && !isNaN(audio.duration)) {
        const targetTime = audio.duration * pct;
        audio.currentTime = targetTime;
        state.currentTime = targetTime;
        this.updateProgressUI(targetTime, audio.duration);
      }
    },

    updateProgressUI(cur, dur) {
      if (!dur || isNaN(dur)) {
        domProgressFill.style.width = '0%';
        domCurrentTime.innerText = '00:00';
        domDuration.innerText = '00:00';
        return;
      }
      const pct = clampVal((cur / dur) * 100, 0, 100);
      domProgressFill.style.width = `${pct}%`;
      domCurrentTime.innerText = formatTime(cur);
      domDuration.innerText = formatTime(dur);
    },

    next() {
      const activeList = getActiveList();
      if (activeList.length === 0) return;

      let nextIdx;
      const mode = modeConfigs[state.modeIndex].mode;
      if (mode === 'shuffle') {
        nextIdx = Math.floor(Math.random() * activeList.length);
      } else {
        nextIdx = (state.currentIndex + 1) % activeList.length;
      }
      this.playTrack(nextIdx);
    },

    prev() {
      const activeList = getActiveList();
      if (activeList.length === 0) return;

      const prevIdx = (state.currentIndex - 1 + activeList.length) % activeList.length;
      this.playTrack(prevIdx);
    },

    toggleMode() {
      state.modeIndex = (state.modeIndex + 1) % modeConfigs.length;
      const cfg = modeConfigs[state.modeIndex];
      domMode.innerText = cfg.text;
    },

    setVolume(val) {
      state.volume = Number(val);
      audio.volume = state.isMuted ? 0 : state.volume / 100;
    },

    toggleMute() {
      state.isMuted = !state.isMuted;
      domMute.innerText = state.isMuted ? '🔇' : '🔊';
      audio.volume = state.isMuted ? 0 : state.volume / 100;
    },

    openPanel() {
      state.isPanelOpen = true;
      this.updateLayout();
      domPanel.classList.add('active');
    },

    closePanel() {
      state.isPanelOpen = false;
      domPanel.classList.remove('active');
    },

    togglePanel() {
      if (state.isPanelOpen) this.closePanel();
      else this.openPanel();
    },

    bindAudioEvents() {
      audio.ontimeupdate = () => {
        if (!state.isSeeking) {
          state.currentTime = audio.currentTime;
          state.duration = audio.duration;
          this.updateProgressUI(audio.currentTime, audio.duration);
        }
      };

      audio.onloadedmetadata = () => {
        state.duration = audio.duration;
        this.updateProgressUI(audio.currentTime, audio.duration);
      };

      audio.onended = () => {
        const mode = modeConfigs[state.modeIndex].mode;
        if (mode === 'repeat_one') {
          audio.currentTime = 0;
          audio.play().catch(() => {});
        } else if (mode === 'play_one_and_stop') {
          this.pause();
        } else {
          this.next();
        }
      };
    },

    bindUiEvents() {
      domPlay.onclick = () => this.togglePlay();
      domPrev.onclick = () => this.prev();
      domNext.onclick = () => this.next();
      domMode.onclick = () => this.toggleMode();
      domMute.onclick = () => this.toggleMute();
      domClose.onclick = () => this.closePanel();
      domBtnMobileClose.onclick = () => this.closePanel();
      domVol.oninput = (e) => this.setVolume(e.target.value);

      domTabAll.onclick = () => this.switchView('all');
      domTabFav.onclick = () => this.switchView('fav');

      domBtnFavMain.onclick = () => {
        const activeList = getActiveList();
        if (activeList[state.currentIndex]) {
          this.toggleFavorite(activeList[state.currentIndex].id);
        }
      };

      const getProgressPct = (e) => {
        const rect = domProgressBar.getBoundingClientRect();
        return (e.clientX - rect.left) / rect.width;
      };

      domProgressBar.addEventListener('pointerdown', (e) => {
        state.isSeeking = true;
        this.seekPercent(getProgressPct(e));

        const onPointerMove = (moveEv) => {
          if (state.isSeeking) {
            const pct = getProgressPct(moveEv);
            if (audio.duration) {
              const preview = audio.duration * clampVal(pct, 0, 1);
              this.updateProgressUI(preview, audio.duration);
            }
          }
        };

        const onPointerUp = (upEv) => {
          if (state.isSeeking) {
            this.seekPercent(getProgressPct(upEv));
            state.isSeeking = false;
          }
          hostWindow.removeEventListener('pointermove', onPointerMove);
          hostWindow.removeEventListener('pointerup', onPointerUp);
        };

        hostWindow.addEventListener('pointermove', onPointerMove);
        hostWindow.addEventListener('pointerup', onPointerUp);
      });

      const onResize = () => this.updateLayout();
      hostWindow.addEventListener('resize', onResize);
      if (hostWindow.visualViewport) {
        hostWindow.visualViewport.addEventListener('resize', onResize);
      }
    },

    bindFabPointer() {
      let dragStart = { x: 0, y: 0 };
      let dragBase = { x: 0, y: 0 };
      let hasMoved = false;

      const onFabPointerDown = (e) => {
        if (e.button !== 0 && e.button !== undefined) return;
        e.preventDefault();
        state.isDragging = false;
        hasMoved = false;
        dragStart = { x: e.clientX, y: e.clientY };
        dragBase = { x: state.fabPos.x, y: state.fabPos.y };

        hostWindow.addEventListener('pointermove', onFabPointerMove);
        hostWindow.addEventListener('pointerup', onFabPointerUp);
      };

      const onFabPointerMove = (e) => {
        const dx = e.clientX - dragStart.x;
        const dy = e.clientY - dragStart.y;
        if (!hasMoved && Math.abs(dx) <= DRAG_THRESHOLD && Math.abs(dy) <= DRAG_THRESHOLD) {
          return;
        }
        hasMoved = true;
        state.isDragging = true;
        domFab.classList.add('is-dragging');
        this.setFabPos(dragBase.x + dx, dragBase.y + dy);
      };

      const onFabPointerUp = () => {
        hostWindow.removeEventListener('pointermove', onFabPointerMove);
        hostWindow.removeEventListener('pointerup', onFabPointerUp);
        state.isDragging = false;
        domFab.classList.remove('is-dragging');

        if (!hasMoved) {
          this.togglePanel();
        }
      };

      domFab.addEventListener('pointerdown', onFabPointerDown);
    },

    bindSwipeGesture() {
      let swipeStartY = 0;
      let swipeStartTime = 0;

      domSwipeHint.addEventListener('pointerdown', (e) => {
        if (hostWindow.innerWidth > 768) return;
        e.preventDefault();
        swipeStartY = e.clientY;
        swipeStartTime = Date.now();

        const onSwipeMove = (moveEv) => {
          const dy = moveEv.clientY - swipeStartY;
          if (dy > 0) {
            domPanel.style.transform = `translateY(${dy}px)`;
          }
        };

        const onSwipeUp = (upEv) => {
          hostWindow.removeEventListener('pointermove', onSwipeMove);
          hostWindow.removeEventListener('pointerup', onSwipeUp);
          const dy = upEv.clientY - swipeStartY;
          const dt = Date.now() - swipeStartTime;

          if (dy > 50 || (dy > 25 && dt < 200)) {
            this.closePanel();
          } else {
            domPanel.style.transform = 'translateY(0)';
          }
        };

        hostWindow.addEventListener('pointermove', onSwipeMove);
        hostWindow.addEventListener('pointerup', onSwipeUp);
      });
    }
  };

  // 10. 注册酒馆助手脚本按钮
  if (typeof appendInexistentScriptButtons === 'function') {
    appendInexistentScriptButtons([
      { name: '🎵 打开雅乐坊', visible: true },
      { name: '🔄 重置雅乐坊位置', visible: true },
      { name: '⏯️ 播放/暂停', visible: true },
      { name: '⏭️ 下一首BGM', visible: true }
    ]);
  }

  if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
    eventOn(getButtonEvent('🎵 打开雅乐坊'), () => BgmController.openPanel());
    eventOn(getButtonEvent('🔄 重置雅乐坊位置'), () => BgmController.resetPosition());
    eventOn(getButtonEvent('⏯️ 播放/暂停'), () => BgmController.togglePlay());
    eventOn(getButtonEvent('⏭️ 下一首BGM'), () => BgmController.next());
  }

  if (typeof initializeGlobal === 'function') {
    initializeGlobal('OnmyojiBgm', BgmController);
  }
  hostWindow.OnmyojiBgm = BgmController;

  BgmController.init();
})();

