@keyframes ascend { 0% { transform: translateY(0) scale(0.5); opacity: 0; } 5% { opacity: 1; } 50% { opacity: 0.9; } 95% { opacity: 0.3; } 100% { transform: translateY(-800px) scale(1.5); opacity: 0; } }

/* 3D法阵层 */
.scene-3d { position: absolute; top: 60%; left: 50%; transform: translate(-50%, -50%) scale(0.8); perspective: 1200px; perspective-origin: 50% 50%; display: flex; align-items: center; justify-content: center; z-index: 0; pointer-events: none; will-change: transform; }
.wuxing-wrapper { position: relative; width: 520px; height: 520px; transform: rotateX(15deg) rotateY(0deg); transform-style: preserve-3d; will-change: transform;}
.ground-glow { position: absolute; top: 50%; left: 50%; width: 500px; height: 500px; margin: -250px 0 0 -250px; border-radius: 50%; background: radial-gradient(circle, rgba(255, 223, 115, 0.25) 0%, rgba(155, 89, 182, 0.15) 40%, transparent 70%); filter: blur(40px); animation: groundPulse 3s ease-in-out infinite; will-change: transform, opacity;}
@keyframes groundPulse { 0%, 100% { transform: scale(1); opacity: 0.7; } 50% { transform: scale(1.1); opacity: 1; } }
.energy-ring { position: absolute; top: 50%; left: 50%; border-radius: 50%; pointer-events: none; will-change: transform;}
.ring-1 { width: 490px; height: 490px; margin: -245px 0 0 -245px; border: 3px solid transparent; background: conic-gradient(from 0deg, var(--gold), var(--red-bright), var(--purple-bright), var(--gold)) border-box; -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #fff calc(100% - 2px)); opacity: 0.6; filter: blur(1px); animation: spin-inf 25s linear infinite; }
.ring-2 { width: 470px; height: 470px; margin: -235px 0 0 -235px; border: 2px solid rgba(255, 223, 115, 0.5); box-shadow: 0 0 20px rgba(255, 223, 115, 0.4), 0 0 40px rgba(255, 107, 91, 0.3), inset 0 0 20px rgba(255, 223, 115, 0.2); animation: spin-inf 35s linear infinite reverse; }
.ring-3 { width: 450px; height: 450px; margin: -225px 0 0 -225px; border: 1px dashed rgba(255, 107, 91, 0.5); box-shadow: 0 0 30px rgba(255, 107, 91, 0.4); animation: spin-inf 45s linear infinite; }
.ring-4 { width: 430px; height: 430px; margin: -215px 0 0 -215px; border: 1px solid rgba(195, 155, 211, 0.4); box-shadow: 0 0 25px rgba(195, 155, 211, 0.4), inset 0 0 15px rgba(195, 155, 211, 0.3); animation: spin-inf 50s linear infinite reverse; }
@keyframes spin-inf { 100% { transform: rotate(360deg); } }
.sixiang-svg { position: absolute; width: 80px; height: 80px; opacity: 0.9; filter: drop-shadow(0 0 10px var(--gold-bright)); }
.sixiang-qinglong { top: 5px; right: 5px; } .sixiang-baihu { bottom: 5px; left: 5px; } .sixiang-zhuque { top: 5px; left: 5px; } .sixiang-xuanwu { bottom: 5px; right: 5px; }
.spin-60-rev-g { animation: spin-inf 60s linear infinite reverse; transform-origin: 0 0;}
.spin-30-g { animation: spin-inf 30s linear infinite; transform-origin: 0 0;}
.spin-20-rev-g { animation: spin-inf 20s linear infinite reverse; transform-origin: 0 0;}
.spell-ring { position: absolute; top: 50%; left: 50%; width: 0; height: 0; animation: spin-inf 15s linear infinite; filter: drop-shadow(0 0 8px var(--gold-bright)); will-change: transform;}
.spell-char { position: absolute; color: rgba(255, 235, 130, 0.9); font-size: 20px; font-weight: bold; text-shadow: 0 0 10px var(--red-bright), 0 0 20px var(--purple-bright); transform-origin: 0 0; white-space: nowrap; }
.seal-star-outer { position: absolute; top: 50%; left: 50%; width: 260px; height: 260px; margin: -130px 0 0 -130px; filter: drop-shadow(0 0 20px var(--gold-bright)) drop-shadow(0 0 40px var(--red-bright)) blur(2px); opacity: 0.6; animation: spin-inf 30s linear infinite reverse; will-change: transform;}
.center-magatama-outer { position: absolute; top: 50%; left: 50%; width: 80px; height: 80px; margin: -40px 0 0 -40px; filter: drop-shadow(0 0 30px var(--gold-bright)) drop-shadow(0 0 60px var(--red-bright)) blur(4px); opacity: 0.7; animation: pulseBlur 2s ease-in-out infinite; will-change: transform, opacity;}
@keyframes pulseBlur { 0%, 100% { opacity: 0.5; transform: scale(1); } 50% { opacity: 0.8; transform: scale(1.2); } }
.center-magatama { position: absolute; top: 50%; left: 50%; width: 60px; height: 60px; margin: -30px 0 0 -30px; filter: drop-shadow(0 0 20px var(--gold-bright)) drop-shadow(0 0 40px var(--red-bright)); animation: pulse 2s ease-in-out infinite; will-change: transform;}
@keyframes pulse { 0%, 100% { transform: translate(-50%, -50%) scale(1); } 50% { transform: translate(-50%, -50%) scale(1.12); } }
.center-glow { position: absolute; top: 50%; left: 50%; width: 120px; height: 120px; margin: -60px 0 0 -60px; border-radius: 50%; background: radial-gradient(circle, rgba(255, 235, 130, 0.5) 0%, rgba(255, 107, 91, 0.2) 50%, transparent 70%); filter: blur(15px); animation: centerGlow 2.5s ease-in-out infinite; will-change: transform, opacity;}
@keyframes centerGlow { 0%, 100% { transform: scale(1); opacity: 0.7; } 50% { transform: scale(1.2); opacity: 1; } }
.bagua-text { font-size: 20px; fill: var(--gold-bright); filter: drop-shadow(0 0 10px var(--red-bright)); font-weight: bold; }
.dizhi-text { font-size: 14px; fill: rgba(255, 235, 130, 0.8); filter: drop-shadow(0 0 8px var(--red-bright)); font-weight: bold; }
.magic-circle-bg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 0.08; filter: drop-shadow(0 0 20px var(--purple-bright)); }
.inner-3d-ring { position: absolute; top: 50%; left: 50%; border-radius: 50%; will-change: transform;}
.inner-3d-1 { width: 310px; height: 310px; margin: -155px 0 0 -155px; border: 2px solid rgba(255, 223, 115, 0.3); animation: spin-inf 40s linear infinite; }
.inner-3d-2 { width: 290px; height: 290px; margin: -145px 0 0 -145px; border: 1px solid rgba(255, 107, 91, 0.3); animation: spin-inf 38s linear infinite reverse; }

/* ================= 内部 UI 元素 ================= */
.event-ticker {
  background: linear-gradient(90deg, transparent, rgba(255,107,91,0.4), transparent);
  color: #fff0f0; text-align: center; padding: 8px 15px; font-size: 0.85rem;
  letter-spacing: 2px; position: relative; z-index: 3; border-bottom: 1px dashed rgba(255,223,115,0.3);
  text-shadow: 0 0 5px rgba(255,107,91,0.8);
}
.scroll-nav {
  display: flex; background: rgba(0,0,0,0.3); position: relative; z-index: 3; padding: 0 20px;
  border-bottom: 1px solid rgba(255,223,115,0.1);
}
.nav-btn {
  padding: 12px 10px; color: #e0d0c0; font-size: 0.95rem; font-weight: bold;
  letter-spacing: 1px; cursor: pointer; transition: 0.3s; position: relative; flex: 1; text-align: center;
}
.nav-btn:hover { color: var(--gold-bright); background: rgba(255,255,255,0.05); }
.nav-btn.active { background: linear-gradient(0deg, rgba(255,107,91,0.2) 0%, transparent 100%); color: var(--gold-bright); text-shadow: 0 0 10px rgba(255,223,115,0.8); }
.nav-btn.active::after { content: ""; position: absolute; bottom: 0; left: 10%; width: 80%; height: 3px; background: var(--red-bright); box-shadow: 0 0 10px var(--red-bright), 0 -5px 15px rgba(255,107,91,0.5); border-radius: 2px 2px 0 0;}

.scroll-content {
  background: rgba(55, 40, 60, 0.4); backdrop-filter: blur(3px);
  position: relative; z-index: 2; height: 500px; padding: 20px;
  display: flex; flex-direction: column;
}
.panel { display: none; flex: 1; overflow-y: auto; overflow-x: hidden; padding-right: 10px; animation: unfold 0.5s cubic-bezier(0.2, 0.8, 0.2, 1); }
.panel.active { display: block; }
.panel::-webkit-scrollbar { width: 6px; }
.panel::-webkit-scrollbar-track { background: rgba(255,255,255,0.05); border-radius: 3px; }
.panel::-webkit-scrollbar-thumb { background: rgba(212,175,55,0.5); border-radius: 3px; }
.panel::-webkit-scrollbar-thumb:hover { background: var(--gold-bright); }
@keyframes unfold { 0% { opacity: 0; transform: translateY(15px); } 100% { opacity: 1; transform: translateY(0); } }

/* ================= 内部排版装饰 ================= */
.hero-layout { display: grid; grid-template-columns: 1fr 2fr; gap: 20px; }
.hero-left { border-right: 2px dashed rgba(255,223,115,0.4); padding-right: 20px; display: flex; flex-direction: column; align-items: center; position: relative;}
.hero-left::after { content:"✨"; position:absolute; right:-12px; top:50%; transform:translateY(-50%); font-size:1.2rem; filter:drop-shadow(0 0 5px var(--gold-bright));}
.hero-name-vert { writing-mode: vertical-rl; text-orientation: upright; font-size: 2.4rem; font-weight: 900; color: var(--gold-bright); letter-spacing: 12px; margin: 10px 0; text-shadow: 0 0 15px rgba(255,223,115,0.6), 2px 2px 0px rgba(0,0,0,0.5); }
.hero-status { margin-top: 15px; padding: 8px 15px; background: linear-gradient(90deg, transparent, rgba(255,223,115,0.1), transparent); color: var(--gold-bright); border-top: 1px solid var(--gold-bright); border-bottom: 1px solid var(--gold-bright); font-size: 0.9rem; width: 100%; text-align: center; font-weight:bold;}
.amulet-count-box { margin-top: 15px; font-size: 0.95rem; color: #ffeeee; font-weight: bold; background: rgba(255,107,91,0.35); padding: 5px 15px; border-radius: 20px; border: 1px solid rgba(255,107,91,0.7); display: none; justify-content: center; align-items: center; width: 100%; text-shadow: 0 0 8px rgba(255,107,91,0.6); box-shadow: 0 0 10px rgba(255,107,91,0.3); }

.attr-list { display: flex; flex-direction: column; gap: 10px; }
.attr-row { display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,223,115,0.15); padding-bottom: 5px; transition: 0.2s;}
.attr-row:hover { background: rgba(255,255,255,0.05); padding-left: 5px; padding-right: 5px;}
.attr-k { color: #f0e0d0; font-size: 0.85rem; }
.attr-v { color: #ffffff; font-weight: bold; text-align: right; text-shadow: 0 0 5px rgba(255,255,255,0.3);}

.section-mark { display: flex; align-items: center; gap: 10px; margin: 25px 0 15px 0; color: var(--gold-bright); font-weight: bold; font-size: 1.1rem; text-shadow: 0 0 8px rgba(255,223,115,0.6); }
.section-mark::before { content: "✦"; color: var(--red-bright); filter: drop-shadow(0 0 3px var(--red-bright));}
.section-mark::after { content: ""; flex: 1; height: 2px; background: linear-gradient(90deg, rgba(255,223,115,0.6), transparent); }

.amulet-grid { display: flex; flex-wrap: wrap; gap: 12px; }
.amulet { background: linear-gradient(135deg, rgba(50, 70, 90, 0.7) 0%, rgba(30, 45, 60, 0.7) 100%); border: 1px solid #71a9c4; border-radius: 6px; padding: 12px; width: calc(50% - 6px); position: relative; transition: 0.3s; backdrop-filter: blur(4px); box-shadow: inset 0 0 10px rgba(113, 169, 196, 0.2);}
.amulet:hover { border-color: #aed6f1; box-shadow: 0 0 15px rgba(133, 193, 233, 0.5), inset 0 0 15px rgba(133, 193, 233, 0.3); transform: translateY(-2px);}
.amulet::before { content: "咒"; position: absolute; top: -12px; left: 50%; transform: translateX(-50%); background: #1b2631; border: 1px solid #85c1e9; color: #fff; font-size: 0.65rem; padding: 2px 8px; border-radius: 3px; box-shadow: 0 0 5px rgba(133,193,233,0.5);}
.amulet-name { color: #aed6f1; font-weight: bold; font-size: 1rem; margin-bottom: 8px; text-align: center; border-bottom: 1px dashed rgba(133,193,233,0.4); padding-bottom: 5px; text-shadow: 0 0 5px rgba(133,193,233,0.5);}
/* 增加强制换行，防止长文本撑破容器 */
.amulet-desc { font-size: 0.75rem; color: #d6eaf8; line-height: 1.5; word-break: break-all; white-space: normal; }

/* 卡片样式 */
.shikigami-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 18px; padding-bottom: 10px; align-items: start; }
.shiki-card { background: linear-gradient(135deg, rgba(75, 55, 80, 0.7) 0%, rgba(45, 30, 50, 0.8) 100%); border: 1px solid rgba(255,223,115,0.4); border-radius: 8px; padding: 15px; position: relative; display: flex; flex-direction: column; gap: 8px; cursor: pointer; transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); height: max-content; backdrop-filter: blur(6px); box-shadow: 0 5px 15px rgba(0,0,0,0.3);}
.shiki-card:hover { transform: translateY(-5px) scale(1.02); border-color: var(--gold-bright); box-shadow: 0 10px 25px rgba(255,223,115,0.3), inset 0 0 15px rgba(255,223,115,0.1); z-index: 2;}
.shiki-card::after { content: "❀"; position: absolute; top: 5px; right: 5px; color: rgba(255,107,91,0.4); font-size: 1.2rem; pointer-events: none; }
.shiki-head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 1px solid rgba(255,107,91,0.4); padding-bottom: 6px; pointer-events: none;}
.shiki-name { font-size: 1.15rem; font-weight: bold; color: var(--gold-bright); text-shadow: 0 0 8px rgba(255,223,115,0.5); }
.shiki-present { font-size: 0.7rem; background: rgba(255,223,115,0.2); border: 1px solid var(--gold-bright); color: var(--gold-bright); padding: 2px 8px; border-radius: 12px; box-shadow: 0 0 5px rgba(255,223,115,0.3);}
.shiki-tags { display: flex; flex-wrap: wrap; gap: 5px; pointer-events: none;}
.s-tag { font-size: 0.65rem; border: 1px solid rgba(255,255,255,0.2); padding: 2px 6px; color: #fff; border-radius: 3px; background: rgba(0,0,0,0.3); }
.magatama-bar { display: flex; align-items: center; gap: 5px; margin-top: 5px; pointer-events: none;}
.magatama { font-size: 0.8rem; color: rgba(255,255,255,0.2); }
.magatama.active { color: var(--red-bright); text-shadow: 0 0 10px rgba(255,107,91,0.9); }
.magatama.blue { color: #5dade2; text-shadow: 0 0 10px rgba(93,173,226,0.9); }
/* 增加强制换行，防止长文本撑破容器 */
.shiki-thought { margin-top: auto; background: rgba(0,0,0,0.4); padding: 10px; font-size: 0.75rem; color: #fdfefe; border-left: 3px solid var(--purple-bright); font-style: italic; line-height: 1.5; pointer-events: none; border-radius: 0 4px 4px 0; word-break: break-all; white-space: normal;}

.lantern-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 15px; padding-top: 5px; padding-bottom: 10px; }
.lantern { background: linear-gradient(to bottom, rgba(50, 35, 55, 0.8), rgba(30, 20, 35, 0.9)); border: 1px solid rgba(255,223,115,0.4); border-radius: 6px; padding: 12px; text-align: center; position: relative; backdrop-filter: blur(4px); box-shadow: 0 5px 10px rgba(0,0,0,0.3); transition:0.3s;}
.lantern:hover { border-color: var(--gold-bright); box-shadow: 0 0 15px rgba(255,223,115,0.3); transform: translateY(-3px);}
.lantern::before { content: ""; position: absolute; top: -15px; left: 50%; transform: translateX(-50%); width: 2px; height: 15px; background: var(--gold-bright); opacity: 0.8; box-shadow: 0 0 5px var(--gold-bright);}
.lantern-name { font-size: 1.05rem; font-weight: bold; color: var(--gold-bright); margin-bottom: 10px; border-bottom: 1px dashed rgba(255,223,115,0.4); padding-bottom: 5px; text-shadow: 0 0 8px rgba(255,223,115,0.5); }
.lantern-stat { font-size: 0.8rem; color: #f0e0d0; display: flex; justify-content: space-between; margin-bottom: 4px; align-items: center;}
.lantern-val { font-weight: bold; color: #ffcccc; font-size: 0.9rem; text-shadow: 0 0 5px rgba(255,107,91,0.5);}
.empty-state { text-align: center; color: #e0d0c0; font-size: 0.95rem; padding: 50px; letter-spacing: 3px; font-style: italic;}

.item-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 15px; padding-bottom: 10px; align-items: start; }
.item-card { background: linear-gradient(135deg, rgba(65, 45, 70, 0.8), rgba(40, 25, 45, 0.9)); border: 1px solid rgba(255,223,115,0.4); border-radius: 8px; padding: 15px; display: flex; flex-direction: column; gap: 8px; backdrop-filter: blur(5px); height: max-content; transition:0.3s; box-shadow: 0 5px 10px rgba(0,0,0,0.3);}
.item-card:hover { border-color: var(--gold-bright); box-shadow: 0 0 15px rgba(255,223,115,0.2); transform: translateY(-2px);}
.item-head { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px dashed rgba(255,223,115,0.5); padding-bottom: 6px; }
.item-name { font-size: 1.1rem; font-weight: bold; color: var(--gold-bright); text-shadow: 0 0 8px rgba(255,223,115,0.4); }
.item-count { background: rgba(0,0,0,0.5); color: var(--gold-bright); font-size: 0.8rem; padding: 2px 8px; border-radius: 12px; border: 1px solid var(--gold-bright); box-shadow: 0 0 5px rgba(255,223,115,0.3);}
.item-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.i-tag { font-size: 0.7rem; padding: 2px 6px; border-radius: 3px; border: 1px solid; }
.i-tag.type { border-color: rgba(93,173,226,0.8); color: #aed6f1; background: rgba(93,173,226,0.2); text-shadow: 0 0 3px rgba(93,173,226,0.5);}
.i-tag.rank { border-color: var(--gold-bright); color: var(--gold-bright); background: rgba(255,223,115,0.2); text-shadow: 0 0 3px rgba(255,223,115,0.5);}
/* 增加强制换行，防止长文本撑破容器 */
.item-desc { font-size: 0.85rem; color: #f0e0d0; line-height: 1.5; margin-top: 5px; word-break: break-all; white-space: normal; }

/* 模态框及大图 */
.shiki-modal-overlay { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); z-index: 10; backdrop-filter: blur(8px); align-items: center; justify-content: center; }
.shiki-modal-overlay.active { display: flex; animation: fadeIn 0.3s ease; }
.shiki-modal-content { background: linear-gradient(135deg, rgba(55,40,60,0.95), rgba(30,20,35,0.98)); border: 2px solid var(--gold-bright); box-shadow: 0 0 50px rgba(255,223,115,0.4), inset 0 0 20px rgba(255,223,115,0.1); border-radius: 12px; width: 90%; max-width: 700px; padding: 30px; position: relative; display: flex; gap: 30px; max-height: 90%; overflow-y: auto; }
.shiki-modal-content::-webkit-scrollbar { width: 6px; }
.shiki-modal-content::-webkit-scrollbar-thumb { background: rgba(255,223,115,0.8); border-radius: 3px; }
.modal-close { position: absolute; top: 15px; right: 20px; font-size: 2rem; color: #e0d0c0; cursor: pointer; transition: 0.2s; z-index: 2; text-shadow: 0 0 5px rgba(0,0,0,0.5);}
.modal-close:hover { color: var(--red-bright); transform: scale(1.1) rotate(90deg); }
.modal-left { flex: 0 0 240px; display: flex; flex-direction: column; align-items: center; gap: 10px; }
.modal-avatar-frame { width: 100%; aspect-ratio: 3/4; border: 2px solid var(--gold-bright); border-radius: 6px; background: #2a1f2d; overflow: hidden; position: relative; cursor: zoom-in; box-shadow: 0 10px 20px rgba(0,0,0,0.5); }
.modal-avatar-frame img { width: 100%; height: 100%; object-fit: cover; transition: 0.4s ease; }
.modal-avatar-frame:hover img { transform: scale(1.08); }
.modal-right { flex: 1; display: flex; flex-direction: column; gap: 15px; }
.modal-name { font-size: 2rem; font-weight: bold; color: var(--red-bright); border-bottom: 2px solid rgba(255,223,115,0.5); padding-bottom: 8px; text-shadow: 0 0 10px rgba(255,107,91,0.6); letter-spacing: 2px;}
.modal-right .attr-k { font-size: 1rem; color: #f0e0d0; }
.modal-right .attr-v { font-size: 1.1rem; color: #fff; font-weight:bold; text-shadow: 0 0 5px rgba(255,255,255,0.3);}
/* 增加强制换行，防止长文本撑破容器 */
.modal-thought { background: rgba(0,0,0,0.4); padding: 15px; border-radius: 6px; border-left: 4px solid var(--purple-bright); font-size: 1.05rem; color: #fdfefe; font-style: italic; margin-top: auto; line-height: 1.6; box-shadow: inset 0 0 10px rgba(0,0,0,0.5); word-break: break-all; white-space: normal;}
.modal-skills { display: none; background: rgba(0,0,0,0.3); padding: 12px; border-radius: 6px; border: 1px solid rgba(133,193,233,0.3); margin-top: 5px; }

.image-viewer-overlay { display: none; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: rgba(0,0,0,0.9); z-index: 20; backdrop-filter: blur(8px); align-items: center; justify-content: center; }
.image-viewer-overlay.active { display: flex; animation: fadeIn 0.3s ease; }
.image-viewer-content { position: relative; max-width: 95%; max-height: 95%; display: flex; align-items: center; justify-content: center; }
.image-viewer-content img { max-width: 100%; max-height: 100%; object-fit: contain; border: 2px solid var(--gold-bright); border-radius: 6px; box-shadow: 0 10px 50px rgba(255,223,115,0.4); }
.viewer-close { position: absolute; top: -20px; right: -20px; background: rgba(55,40,60,0.9); border: 2px solid var(--gold-bright); color: var(--gold-bright); width: 45px; height: 45px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.8rem; cursor: pointer; transition: 0.3s; z-index: 21; box-shadow: 0 0 15px rgba(255,223,115,0.5);}
.viewer-close:hover { background: var(--red-bright); color: #fff; transform: scale(1.1) rotate(90deg); border-color: var(--red-bright); box-shadow: 0 0 20px var(--red-bright);}

/* ================= 移动端极致性能降级适配 ================= */
@media(max-width: 600px) {
  * { backdrop-filter: none !important; filter: none !important; }
  .onmyoji-scroll { box-shadow: 0 5px 15px rgba(0,0,0,0.5) !important; }
  .scroll-header { flex-direction: column; align-items: flex-start; gap: 8px; padding: 12px; background-color: rgba(55, 40, 60, 0.95) !important; box-shadow: none !important; }
  .world-title { font-size: 1.15rem; text-shadow: none !important; }
  .world-stats { width: 100%; justify-content: space-between; padding: 6px 12px; box-shadow: none !important;}
