    "虫师": "https://origin.picgo.net/2026/06/02/930d58478eb4710362b0e0aa4ae12a245330285df5d815de.png",
    "天井下": "https://origin.picgo.net/2026/06/02/989ecc66c360982710b007eea4a2b5484035695162043df2.png",
    "数珠": "https://origin.picgo.net/2026/06/02/aa5376030ecd66a4636336bb8b3b4d9a2977bac1a30ad8a7.png",
    "萤草": "https://origin.picgo.net/2026/06/02/93fbd941a771b16858694b697db196b2735c0c3e7c7b97ee.png",
  };
  const defaultAvatar = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' fill='%232a1f2d'/><text x='50' y='55' font-size='40' fill='%23ffdf73' text-anchor='middle' alignment-baseline='middle'>?</text></svg>";

  function populateData() {
    const all_variables = getAllVariables();
    const sd = _.get(all_variables, 'stat_data', {});

    $('#v-loc').text(_.get(sd, '世界.当前位置', '未知地界'));
    $('#v-time').text(_.get(sd, '世界.时间', '未知时辰'));
    $('#v-event').text(_.get(sd, '世界.大事件', '平安京风平浪静，未有妖气作祟。'));

    const name = _.get(sd, '主角.姓名', '无名氏');
    $('#v-name').text(name);
    $('#v-gender').text(_.get(sd, '主角.性别', '未知'));
    $('#v-race').text(_.get(sd, '主角.种族', '未知'));
    $('#v-id').text(_.get(sd, '主角.身份', '未知'));
    $('#v-fac').text(_.get(sd, '主角.所属势力', '无'));
    $('#v-status').text('当前：' + _.get(sd, '主角.当前状态', '正常'));

    const isOnmyoji = _.get(sd, '主角.是否为阴阳师', false);
    const isGameMode = _.get(sd, '主角.是否为游戏模式', false);

    if (isOnmyoji) {
      $('#nav-shiki').show();
    } else {
      $('#nav-shiki').hide();
      if ($('#nav-shiki').hasClass('active')) {
        $('.nav-btn[data-t="p1"]').click();
      }
    }

    if (isGameMode) {
      $('#v-amulet-count').css('display', 'flex');
      $('#v-amulet-num').text(_.get(sd, '主角.召唤符咒数量', 0));
    } else {
      $('#v-amulet-count').hide();
    }

    /* P1: 技能 */
    const skills = _.get(sd, '主角.技能', {});
    const $skills = $('#skills-container');
    $skills.empty();
    if(_.isEmpty(skills)) {
      $skills.html('<div class="empty-state">灵力微弱，尚未结下术法之印</div>');
    } else {
      _.forEach(skills, (data, sName) => {
        $skills.append(`
          <div class="amulet">
            <div class="amulet-name">${sName}</div>
            <div class="amulet-desc">${data.描述 || '...'}</div>
          </div>
        `);
      });
    }

    /* P2: 缘结 */
    const relations = _.get(sd, '人际关系', {});
    const $rels = $('#relations-container');
    $rels.empty();
    if(_.isEmpty(relations)) {
      $rels.html('<div class="empty-state">现世孤寂，尚未结下羁绊</div>');
    } else {
      _.forEach(relations, (data, rName) => {
        const fav = data.好感度 || 0;
        let magaHtml = '<span style="font-size:0.75rem; color:#aaa; margin-right:5px">羁绊</span>';
        const num = Math.min(5, Math.max(1, Math.ceil(Math.abs(fav) / 20)));
        const isNeg = fav < 0;

        if(fav === 0) {
          magaHtml += '<span class="magatama">☯ 平淡</span>';
        } else {
          for(let i=0; i<5; i++) {
            if(i < num) {
              magaHtml += `<span class="magatama active ${isNeg?'blue':''}">${isNeg?'❄':'🔥'}</span>`;
            } else {
              magaHtml += `<span class="magatama">○</span>`;
            }
          }
          magaHtml += `<span style="font-size:0.7rem; margin-left:5px; color:${isNeg?'var(--blue)':'var(--red-bright)'}; font-weight:bold;">${fav}</span>`;
        }

        const pre = data.是否在场 ? '<span class="shiki-present">在场</span>' : '';

        $rels.append(`
          <div class="shiki-card" data-name="${rName}" data-type="relation">
            <div class="shiki-head">
              <span class="shiki-name">${rName}</span>
              ${pre}
            </div>
            <div class="shiki-tags">
              <span class="s-tag">${data.身份 || '未知'}</span>
              <span class="s-tag">${data.种族 || '未知'}</span>
              <span class="s-tag">${data.所属势力 || '无派'}</span>
              <span class="s-tag" style="border-color:var(--gold-bright); color:var(--gold-bright); box-shadow:0 0 5px rgba(255,223,115,0.3)">${data.当前状态 || '未知'}</span>
            </div>
            <div class="magatama-bar">${magaHtml}</div>
            <div class="shiki-thought">『${data.内心想法 || '...'}』</div>
          </div>
        `);
      });
    }

    /* P3: 势力 */
    const factions = _.get(sd, '势力关系', {});
    const $facs = $('#factions-container');
    $facs.empty();
    if(_.isEmpty(factions)) {
      $facs.html('<div class="empty-state">三界六道，尚未留下威名</div>');
    } else {
      _.forEach(factions, (data, fName) => {
        let fCol = '#fff';
        if(data.好感度 > 0) fCol = 'var(--red-bright)';
        if(data.好感度 < 0) fCol = '#85c1e9';

        $facs.append(`
          <div class="lantern">
            <div class="lantern-name">${fName}</div>
            <div class="lantern-stat">
              <span>好感</span>
              <span class="lantern-val" style="color:${fCol}">${data.好感度}</span>
            </div>
            <div class="lantern-stat">
              <span>声望</span>
              <span class="lantern-val" style="color:var(--gold-bright)">${data.声望值}</span>
            </div>
          </div>
        `);
      });
    }

    /* P4: 持有物品 */
    const items = _.get(sd, '主角.持有物品', {});
    const $items = $('#items-container');
    $items.empty();
    if(_.isEmpty(items)) {
      $items.html('<div class="empty-state">行囊空空，未拾得现世珍物</div>');
    } else {
      _.forEach(items, (data, iName) => {
        if(data.数量 > 0) {
          $items.append(`
            <div class="item-card">
              <div class="item-head">
                <span class="item-name">${iName}</span>
                <span class="item-count">x${data.数量}</span>
              </div>
              <div class="item-tags">
                ${data.类型 ? `<span class="i-tag type">${data.类型}</span>` : ''}
                ${data.品阶 ? `<span class="i-tag rank">${data.品阶}</span>` : ''}
              </div>
              <div class="item-desc">${data.作用 || '无特殊作用'}</div>
            </div>
          `);
        }
      });
    }

    /* P5: 式神录 */
    if (isOnmyoji) {
      const shikigamis = _.get(sd, '式神录', {});
      const $roster = $('#shiki-roster-container');
      $roster.empty();
      if(_.isEmpty(shikigamis)) {
        $roster.html('<div class="empty-state">灵符未动，尚未结契式神</div>');
      } else {
        _.forEach(shikigamis, (data, sName) => {
          let gameModeHtml = '';
          if (isGameMode) {
            const expPercent = data.升级所需经验值 ? Math.min(100, (data.当前经验值 / data.升级所需经验值) * 100) : 0;
            gameModeHtml = `
              <div style="margin-top: 8px; border-top: 1px dashed rgba(255,223,115,0.4); padding-top: 8px;">
                <div style="display:flex; justify-content:space-between; font-size:0.8rem; font-weight:bold; color:var(--ink);">
                  <span style="text-shadow: 0 0 5px rgba(255,255,255,0.5)">${data.星级 || 2}⭐ Lv.${data.等级 || 1}</span>
                  <span style="color:#e0d0c0; font-weight:normal;">EXP: ${Math.floor(data.当前经验值 || 0)}/${Math.floor(data.升级所需经验值 || 0)}</span>
                </div>
                <div style="width:100%; height:5px; background:rgba(0,0,0,0.6); border-radius:3px; margin-top:5px; overflow:hidden; box-shadow:inset 0 0 5px rgba(0,0,0,0.8);">
                  <div style="height:100%; width:${expPercent}%; background:linear-gradient(90deg, var(--gold-bright), #fff0b3); border-radius:3px; box-shadow:0 0 5px var(--gold-bright);"></div>
                </div>
              </div>
            `;
          }

          let skillTags = '';
          if (!_.isEmpty(data.技能)) {
            skillTags = `<div style="font-size:0.75rem; color:#aed6f1; margin-top:4px; font-weight:bold;">术法: ${Object.keys(data.技能).join(' / ')}</div>`;
          }

          $roster.append(`
            <div class="shiki-card shiki-roster-card" data-name="${sName}" data-type="shiki">
              <div class="shiki-head">
                <span class="shiki-name">${sName}</span>
                ${isGameMode && data.稀有度 ? `<span style="color:var(--red-bright); font-weight:900; font-style:italic; font-size:1rem; letter-spacing:1px; text-shadow:0 0 10px rgba(255,107,91,0.8);">${data.稀有度}</span>` : ''}
              </div>
              <div class="shiki-tags" style="margin-top: 6px;">
                <span class="s-tag">${data.种族 || '未知'}</span>
                <span class="s-tag" style="border-color:rgba(93,173,226,0.5); color:#aed6f1">忠诚: ${data.忠诚度 || 0}</span>
                <span class="s-tag" style="border-color:rgba(255,107,91,0.5); color:#ffcccc">好感: ${data.好感度 || 0}</span>
              </div>
              ${skillTags}
              ${gameModeHtml}
              <div style="font-size: 0.8rem; color: #f0e0d0; margin-top: 8px; line-height: 1.5; background:rgba(0,0,0,0.2); padding:6px; border-radius:4px; word-break: break-all; white-space: normal;">
                ${data.描述 || '暂无描述...'}
              </div>
            </div>
          `);
        });
      }
    }
  }

  function openModal(name, type) {
    const all_variables = getAllVariables();
    let data = {};

    $('#modal-name').text(name);

    const imgSrc = avatarMap[name] || defaultAvatar;
    $('#modal-img').attr('src', imgSrc);

    const $attrList = $('#modal-attr-list');
    $attrList.empty();

    if (type === 'relation') {
      data = _.get(all_variables, `stat_data.人际关系.${name}`, {});
      $attrList.append(`<div class="attr-row"><span class="attr-k">身份</span><span class="attr-v">${data.身份 || '未知'}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">种族</span><span class="attr-v">${data.种族 || '未知'}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">势力</span><span class="attr-v">${data.所属势力 || '无派'}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">状态</span><span class="attr-v">${data.当前状态 || '未知'}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">好感</span><span class="attr-v">${data.好感度 || 0}</span></div>`);

      $('#modal-thought').text(`『${data.内心想法 || '...'}』`).show();
      $('#modal-skills').hide();

    } else if (type === 'shiki') {
      data = _.get(all_variables, `stat_data.式神录.${name}`, {});
      if (data.稀有度) {
        $attrList.append(`<div class="attr-row"><span class="attr-k">稀有度</span><span class="attr-v" style="color:var(--red-bright); font-style:italic;">${data.稀有度}</span></div>`);
      }
      $attrList.append(`<div class="attr-row"><span class="attr-k">种族</span><span class="attr-v">${data.种族 || '未知'}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">阶级</span><span class="attr-v">${data.星级 || 2}⭐ Lv.${data.等级 || 1}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">忠诚度</span><span class="attr-v">${data.忠诚度 || 0}</span></div>`);
      $attrList.append(`<div class="attr-row"><span class="attr-k">好感度</span><span class="attr-v">${data.好感度 || 0}</span></div>`);

      $('#modal-thought').text(`${data.描述 || '暂无描述...'}`).show();

      const skills = data.技能 || {};
      const $skillsBox = $('#modal-skills');
      $skillsBox.empty().show();

      if(!_.isEmpty(skills)) {
        $skillsBox.append(`<div style="color:var(--gold-bright); font-size:0.95rem; font-weight:bold; margin-bottom:8px; border-bottom:1px dashed rgba(255,223,115,0.4); padding-bottom:4px;">修习之术</div>`);
        _.forEach(skills, (sData, sName) => {
          $skillsBox.append(`
            <div style="margin-bottom: 8px;">
              <div style="color:#aed6f1; font-weight:bold; font-size:0.9rem; margin-bottom:2px;">【${sName}】</div>
              <div style="color:#e0d0c0; font-size:0.85rem; line-height:1.4; padding-left:5px; border-left:2px solid #5dade2; word-break: break-all; white-space: normal;">${sData.描述 || '暂无详细描述'}</div>
            </div>
          `);
        });
      } else {
        $skillsBox.append(`<div style="color:#e0d0c0; font-size:0.85rem; font-style:italic; text-align:center; padding:10px;">尚未觉醒特殊术法</div>`);
      }
    }

    $('#shiki-modal').addClass('active');
  }

  function initBackground() {
    const isMobile = window.innerWidth <= 600;

    const ring = document.getElementById('spellRing');
    if(ring) {
        const spells = ['臨','兵','闘','者','皆','陣','列','在','前'];
        spells.forEach((char, i) => {
            const angle = (i / spells.length) * 360;
            const span = document.createElement('span');
            span.className = 'spell-char';
            span.textContent = char;
            span.style.transform = `rotate(${angle}deg) translateY(-215px)`;
            ring.appendChild(span);
        });
    }

    const sContainer = document.getElementById('starfield');
    if(sContainer) {
        const starCount = isMobile ? 8 : 60;
        for (let i = 0; i < starCount; i++) {
            const star = document.createElement('div');
            star.className = 'star';
            const size = Math.random() * 2.5 + 1;
            star.style.width = star.style.height = size + 'px';
            star.style.left = Math.random() * 100 + '%';
            star.style.top = Math.random() * 100 + '%';
            star.style.animationDuration = Math.random() * 4 + 2 + 's';
            star.style.animationDelay = Math.random() * 5 + 's';
            if(!isMobile) star.style.boxShadow = `0 0 ${size*4}px ${size>2?'var(--gold-bright)':'var(--purple-bright)'}`;
            sContainer.appendChild(star);
        }
    }

    const pContainer = document.getElementById('ascendingParticles');
    if(pContainer) {
        const colors = ['#ffdf73', '#f0d060', '#ff6b5b', '#e74c3c', '#c39bd3', '#9b59b6'];
        const particleCount = isMobile ? 5 : 40;
        for (let i = 0; i < particleCount; i++) {
            const p = document.createElement('div');
            p.className = 'ascend-particle';
            const size = Math.random() * 5 + 2;
            const color = colors[Math.floor(Math.random() * colors.length)];
            p.style.width = p.style.height = size + 'px';
            p.style.background = color;
            if(!isMobile) p.style.boxShadow = `0 0 ${size*5}px ${color}, 0 0 ${size*10}px ${color}`;
            p.style.left = Math.random() * 100 + '%';
            p.style.bottom = -10 - Math.random() * 30 + 'px';
            p.style.animationDuration = Math.random() * 10 + 8 + 's';
            p.style.animationDelay = Math.random() * 12 + 's';
            pContainer.appendChild(p);
        }
    }

    const sakuraContainer = document.getElementById('sakuraContainer');
    if(sakuraContainer) {
        const sakuraCount = isMobile ? 5 : 30;
        for (let i = 0; i < sakuraCount; i++) {
            const sakura = document.createElement('div');
            sakura.className = 'sakura';
            const size = Math.random() * 8 + 5;
            sakura.style.width = size + 'px';
            sakura.style.height = size + 'px';
            sakura.style.left = Math.random() * 100 + '%';
            sakura.style.top = -20 - Math.random() * 100 + 'px';
            sakura.style.animationDuration = (Math.random() * 5 + 5) + 's, ' + (Math.random() * 3 + 2) + 's';
            sakura.style.animationDelay = Math.random() * 10 + 's, ' + Math.random() * 2 + 's';
            sakuraContainer.appendChild(sakura);
        }
    }
  }

  function bindEvents() {
    $('#toggle-header').on('click', function() {
      const $scroll = $('#main-scroll');
      const $body = $('#scroll-body');
      if ($scroll.hasClass('is-open')) {
        $body.slideUp(300, function() {
          $scroll.removeClass('is-open');
        });
      } else {
        $scroll.addClass('is-open');
        $body.slideDown(300);
      }
    });

    $('.nav-btn').on('click', function() {
      $('.nav-btn').removeClass('active');
      $(this).addClass('active');
      $('.panel').removeClass('active');
      $('#' + $(this).data('t')).addClass('active');
    });

    $('.scroll-content').on('click', '.shiki-card', function() {
      const name = $(this).data('name');
      const type = $(this).data('type');
      openModal(name, type);
    });

    $('#modal-close').on('click', function() {
      $('#shiki-modal').removeClass('active');
    });

    $('#shiki-modal').on('click', function(e) {
      if(e.target === this) {
        $(this).removeClass('active');
      }
    });

    $('.modal-avatar-frame').on('click', function() {
      const src = $('#modal-img').attr('src');
      if(src) {
        $('#viewer-img').attr('src', src);
        $('#image-viewer').addClass('active');
      }
    });

    $('#viewer-close').on('click', function() {
      $('#image-viewer').removeClass('active');
    });

    $('#image-viewer').on('click', function(e) {
      if(e.target === this) {
        $(this).removeClass('active');
      }
    });
  }

  async function init() {
    await waitGlobalInitialized('Mvu');
    initBackground();
    populateData();
    bindEvents();
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => { populateData(); });
  }

  $(errorCatched(init));
</script>
</head>
<body>

<div class="onmyoji-scroll" id="main-scroll">

  <!-- 头部：点击触发展开/折叠 -->
  <div class="scroll-header" id="toggle-header" title="点击展开/折叠状态栏">
    <div class="world-title">平安百物语 <span class="toggle-icon">▼</span></div>
    <div class="world-stats">
      <div class="w-stat">地界 <span class="w-val" id="v-loc">--</span></div>
      <div class="w-stat">时辰 <span class="w-val" id="v-time">--</span></div>
    </div>
  </div>

  <!-- 可折叠的内容区 -->
  <div class="scroll-body" id="scroll-body">

    <div class="cloud-pattern"></div>
    <div class="scroll-corner corner-bl"></div>
    <div class="scroll-corner corner-br"></div>
    <div class="lantern-bg lantern-bg-1"></div>
    <div class="lantern-bg lantern-bg-2"></div>

    <div class="sakura-container" id="sakuraContainer"></div>
    <div class="starfield" id="starfield"></div>
    <div class="ascending-particles" id="ascendingParticles"></div>

    <div class="scene-3d">
        <div class="wuxing-wrapper">
            <div class="ground-glow"></div>
            <div class="energy-ring ring-1"></div>
            <div class="energy-ring ring-2"></div>
            <div class="energy-ring ring-3"></div>
            <div class="energy-ring ring-4"></div>
            <div class="inner-3d-ring inner-3d-1"></div>
            <div class="inner-3d-ring inner-3d-2"></div>

            <svg class="sixiang-svg sixiang-qinglong" viewBox="0 0 50 50">
                <polyline points="10,40 25,30 40,35 45,15 30,5" fill="none" stroke="var(--gold-bright)" stroke-width="2.5"/>
                <circle cx="10" cy="40" r="3.5" fill="var(--red-bright)"/><circle cx="25" cy="30" r="3" fill="var(--gold-bright)"/>
                <circle cx="40" cy="35" r="3" fill="var(--gold-bright)"/><circle cx="45" cy="15" r="3" fill="var(--gold-bright)"/>
                <circle cx="30" cy="5" r="3" fill="var(--gold-bright)"/>
            </svg>
            <svg class="sixiang-svg sixiang-baihu" viewBox="0 0 50 50">
                <polyline points="40,10 25,20 10,15 5,35 20,45" fill="none" stroke="var(--gold-bright)" stroke-width="2.5"/>
                <circle cx="40" cy="10" r="3.5" fill="var(--red-bright)"/><circle cx="25" cy="20" r="3" fill="var(--gold-bright)"/>
                <circle cx="10" cy="15" r="3" fill="var(--gold-bright)"/><circle cx="5" cy="35" r="3" fill="var(--gold-bright)"/>
                <circle cx="20" cy="45" r="3" fill="var(--gold-bright)"/>
            </svg>
            <svg class="sixiang-svg sixiang-zhuque" viewBox="0 0 50 50">
                <polyline points="10,25 25,10 40,25 25,40 10,25" fill="none" stroke="var(--gold-bright)" stroke-width="2.5"/>
                <circle cx="10" cy="25" r="3.5" fill="var(--red-bright)"/><circle cx="25" cy="10" r="3" fill="var(--gold-bright)"/>
                <circle cx="40" cy="25" r="3" fill="var(--gold-bright)"/><circle cx="25" cy="40" r="3" fill="var(--gold-bright)"/>
            </svg>
            <svg class="sixiang-svg sixiang-xuanwu" viewBox="0 0 50 50">
                <polyline points="5,25 25,5 45,25 35,45 15,45 5,25" fill="none" stroke="var(--gold-bright)" stroke-width="2.5"/>
