<script>
    var API_KEY = 'hyakumonogatari_api_config';
    var DRAFT_KEY = 'hyakumonogatari_char_draft';

    var curPaneId = 'home';
    var activeSteps = ['home','gamemode','roletype','basic','appear','identity','arrival','preview'];
    var gameMode = 'immersive';
    var roleType = 'canon';
    var arrivalType = '异邦客';
    var maxStepReached = 0;

    var loadedProfiles = [];
    var _exportIdx = -1;
    var _editingUid = null;
    var _autoSaveTimer = null;

    var BODY_TYPES = ['纤细','匀称','高挑','娇小','健壮','魁梧','瘦削'];
    var HAIR_STYLES = ['长直发','短发','高马尾','披肩散发','编发','双马尾','束发'];
    var FACE_AURA = ['清冷','温婉','英气','邪魅','妩媚','威严','阳光','阴郁'];
    var SPEECH_TONE = ['清冷淡漠','温柔和缓','狂妄嚣张','阴阳怪气','活泼俏皮','威严沉稳','慵懒随意'];
    var SPEECH_HABIT = ['自称"在下"','自称"本大爷"','喜欢用敬语','语速缓慢','爱用反问','说话带笑','惜字如金'];

    function getApiConfig(){try{var s=localStorage.getItem(API_KEY);if(s)return JSON.parse(s)}catch(e){}return{worldbookName:'阴阳师V1.6'};}
    function getWorldbookName(){var cfg=getApiConfig();return cfg.worldbookName||'阴阳师V1.6';}
    function loadApiConfig(){var cfg=getApiConfig();document.getElementById('wbName').value=cfg.worldbookName||'阴阳师V1.6';}
    function saveGlobalConfig(){var cfg=getApiConfig();cfg.worldbookName = document.getElementById('wbName').value.trim()||'阴阳师V1.6';localStorage.setItem(API_KEY,JSON.stringify(cfg));toast('tGlobal','配置保存成功','ok');}

    function getDisplayName(fd) {
        if(fd.roleType === 'canon') return fd.canonName || '未知原著角色';
        return fd.name || '无名氏';
    }

    function getApi(name){try{if(typeof window[name]==='function')return window[name];}catch(e){}return null;}
    function escHtml(s){var d=document.createElement('div');d.textContent=String(s);return d.innerHTML;}
    function toast(id,msg,type){var el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='toast '+type; setTimeout(function(){el.className='toast';},3000);}
    function clearToasts(){document.querySelectorAll('.toast').forEach(function(t){t.className='toast'});}

    function addTag(text,targetId){var el=document.getElementById(targetId);var cur=el.value.trim();if(!cur){el.value=text;return;}var tags=cur.split(/[、,，]/);for(var i=0;i<tags.length;i++){if(tags[i].trim()===text)return;}el.value=cur+'、'+text;}

    function switchSubTab(btn, tabGroupId, paneId){
        document.querySelectorAll('#'+tabGroupId+' .sub-tab').forEach(function(t){t.classList.remove('active');});
        btn.classList.add('active');
        var panesContainer = document.getElementById(tabGroupId+'-panes');
        if(panesContainer){
            panesContainer.querySelectorAll('.sub-tab-pane').forEach(function(p){p.classList.remove('active');});
        }
        var target = document.getElementById(paneId);
        if(target) target.classList.add('active');
    }

    function toggleSingleTag(el,groupId){var siblings=document.getElementById(groupId).querySelectorAll('.tag-chip');var wasActive=el.classList.contains('active');siblings.forEach(function(s){s.classList.remove('active');});if(!wasActive)el.classList.add('active');}
    function getActiveSingleTag(groupId){var el=document.querySelector('#'+groupId+' .tag-chip.active');return el?el.textContent.trim():'';}
    function getActiveMultiTags(container){var tags=[];container.querySelectorAll('.tag-chip.active').forEach(function(t){tags.push(t.textContent.trim());});return tags;}

    function addCustomMultiTag(inputId, groupId){
        var inputEl = document.getElementById(inputId);
        var text = inputEl.value.trim();
        if(!text) return;
        var container = document.getElementById(groupId);
        if(!container) return;
        var chip = document.createElement('span');
        chip.className = 'tag-chip active';
        chip.textContent = text;
        chip.onclick = function(){this.classList.toggle('active');};
        container.appendChild(chip);
        inputEl.value = '';
    }

    function setArrival(btn){document.querySelectorAll('.arrival-btn').forEach(function(b){b.classList.remove('active')});btn.classList.add('active');arrivalType=btn.getAttribute('data-type');}

    document.getElementById('cfg-timeline-node').addEventListener('change', function(){
        document.getElementById('customTimeBox').style.display = (this.value === '自定义时间') ? 'block' : 'none';
    });

    function selectGameMode(mode) {
        gameMode = mode;
        document.querySelectorAll('#pane-gamemode .type-card').forEach(c => c.classList.remove('active'));
        document.getElementById('card-mode-' + mode).classList.add('active');

        var identityInput = document.getElementById('f-identity');
        if (mode === 'game') {
            selectRoleType('custom');
            identityInput.value = '阴阳师';
            identityInput.disabled = true;
        } else {
            identityInput.disabled = false;
        }
    }

    function selectRoleType(type) {
        if (gameMode === 'game' && type === 'canon') {
            return toast('t-roletype', '游戏模式下强制身份为阴阳师，不可扮演原著人物。', 'err');
        }

        roleType = type;
        document.querySelectorAll('#pane-roletype .type-card').forEach(c => c.classList.remove('active'));
        document.getElementById('card-type-' + type).classList.add('active');

        if(type === 'canon') {
            document.getElementById('canonNameBox').style.display = 'block';
            document.getElementById('arrivalMethodGroup').style.display = 'none';
            arrivalType = '原住民';
        } else {
            document.getElementById('canonNameBox').style.display = 'none';
            document.getElementById('arrivalMethodGroup').style.display = 'block';
            arrivalType = '异邦客';
        }
    }

    function bindGrid(containerId, callback) {
        const container = document.getElementById(containerId);
        if(!container) return;
        container.querySelectorAll('.grid-item').forEach(item => {
            item.addEventListener('click', function() {
                container.querySelectorAll('.grid-item').forEach(el => el.classList.remove('selected'));
                this.classList.add('selected');
                if(callback) callback(this);
            });
        });
    }

    bindGrid('sel-gender', function(el) { document.getElementById('f-gender').value = el.dataset.val; });
    bindGrid('sel-faction', function(el) {
        const raceInput = document.getElementById('cfg-race');
        const faction = el.dataset.val;
        const humans = ['平安京', '源氏家族', '贺茂家族', '藤原家族', '阴阳寮', '日轮之城'];
        const demons = ['大江山', '逢魔之原', '黑夜山', '黑晴明阵营', '离岛', '散妖', '梦界'];
        const gods = ['高天原', '严岛'];
        const ghosts = ['冥界', '鬼域'];
        const sea = ['海国', '铃鹿山', '荒川', '永生之海'];
        if(humans.includes(faction)) raceInput.value = '人类';
        else if(demons.includes(faction)) raceInput.value = '大妖/妖族';
        else if(gods.includes(faction)) raceInput.value = '神明';
        else if(ghosts.includes(faction)) raceInput.value = '鬼族';
        else if(sea.includes(faction)) raceInput.value = '海妖/水族';
        else raceInput.value = '未知';
    });

    function buildTagGroup(containerId, items) {
        var c = document.getElementById(containerId);
        if (!c) return;
        var h = '';
        items.forEach(function(item) {
            h += '<span class="tag-chip" onclick="this.classList.toggle(\'active\')">' + item + '</span>';
        });
        c.innerHTML = h;
    }

    function addSpeechSample() {
        var container = document.getElementById('speechSampleList');
        var h = '<div class="form-group" style="padding:10px; background:rgba(0,0,0,0.03); border:1px dashed rgba(44,34,26,0.2); border-radius:2px; margin-bottom:10px; position:relative;">';
        h += '<button style="position:absolute; top:5px; right:5px; background:transparent; border:none; color:var(--red); cursor:pointer;" onclick="this.parentElement.remove()">✕</button>';
        h += '<div class="form-label">场景/情境</div><input class="form-input" style="margin-bottom:8px;" data-ss="scene" placeholder="例如：施展术法时...">';
        h += '<div class="form-label">台词</div><textarea class="form-textarea" data-ss="line" placeholder="原话..."></textarea>';
        h += '</div>';
        container.insertAdjacentHTML('beforeend', h);
    }

    function curStepIndex(){return activeSteps.indexOf(curPaneId);}

    function showPane(paneId){
        document.querySelectorAll('.pane').forEach(function(p){p.classList.remove('active')});
        document.querySelectorAll('.nav-item').forEach(function(p){p.classList.remove('active')});

        var el=document.getElementById('pane-'+paneId);
        if(el){el.classList.add('active');}

        var navEl = document.getElementById('nav-'+paneId);
        if(navEl) navEl.classList.add('active');

        curPaneId=paneId;

        if(activeSteps.includes(paneId)) {
            updStepUI();
            if(paneId === 'preview') buildPreviewCard();
        }
    }

    function updStepUI(){
        var idx=curStepIndex();
        var isHome=(curPaneId==='home');

        for(var i=1; i<activeSteps.length; i++) {
            var stepId = activeSteps[i];
            var navEl = document.getElementById('nav-'+stepId);
            if(navEl) {
                if(roleType === 'canon' && ['basic','appear','identity'].includes(stepId)) {
                    navEl.classList.add('disabled');
                    navEl.onclick = null;
                    continue;
                }

                if(i <= maxStepReached) {
                    navEl.classList.remove('disabled');
                    navEl.onclick = (function(id) { return function() { showPane(id); } })(stepId);
                } else {
                    navEl.classList.add('disabled');
                    navEl.onclick = null;
                }
            }
        }
        document.getElementById('headerDesc').textContent=isHome?'卷轴铺展中...':'铭刻节点 ' + idx + '/' + (activeSteps.length-1);
    }

    function startNewChar(){
        _editingUid = null;
        maxStepReached = 1;
        selectGameMode('immersive');
        selectRoleType('canon');
        showPane('gamemode');
    }

    function navNext(){
        clearToasts();
        var idx=curStepIndex();
        if(idx<0)return;
        var pid=curPaneId;

        if(pid==='roletype'){
            if(roleType === 'canon') {
                if(!document.getElementById('f-canon-name').value.trim()) return toast('t-roletype','请填入你要扮演的原著人物名讳','err');
            }
        } else if(pid==='basic'){
            if(!document.getElementById('f-name').value.trim()) return toast('t-basic','请赐予角色名讳','err');
        }

        saveDraft();

        var nextPaneId = '';
        if(pid === 'roletype' && roleType === 'canon') {
            nextPaneId = 'arrival';
            maxStepReached = Math.max(maxStepReached, activeSteps.indexOf('arrival'));
        } else {
            var nextIdx=idx+1;
            if(nextIdx>=activeSteps.length)return;
            nextPaneId=activeSteps[nextIdx];
            if(nextIdx>maxStepReached)maxStepReached=nextIdx;
        }

        showPane(nextPaneId);
    }

    function navPrev(){
        clearToasts();
        var idx=curStepIndex();
        if(idx<=0)return;
        if(idx===1){showPane('home');return;}

        var prevPaneId = '';
        if(curPaneId === 'arrival' && roleType === 'canon') {
            prevPaneId = 'roletype';
        } else {
            prevPaneId=activeSteps[idx-1];
        }

        showPane(prevPaneId);
    }

    function collectFormData() {
        var factionEl = document.querySelector('#sel-faction .selected');
        var genderEl = document.querySelector('#sel-gender .selected');

        var speechSamples = [];
        document.querySelectorAll('#speechSampleList > div').forEach(function(item) {
            var scene = (item.querySelector('[data-ss="scene"]') || {}).value || '';
            var line = (item.querySelector('[data-ss="line"]') || {}).value || '';
