    // 生成完全自然语言的世界书内容描述，不再附加 JSON，包含所有自定义细节
    function generateNaturalDesc(fd) {
        let desc = "";
        if(fd.roleType === 'canon') {
            desc += `以下为主角设定。《阴阳师》中的角色：【${fd.canonName}】。\n`;
            desc += `该生灵作为【${fd.arrivalType}】，降临于【${fd.timeNode}】的【${fd.locCustom}】。\n`;
            if(fd.specialReq) {
                desc += `身上背负的天命旨意（当前状态）：${fd.specialReq}\n`;
            }
            desc += `\n此生灵的性格、外貌与能力皆遵循《阴阳师》原著的既有传说与设定。`;
        } else {
            desc += `以下为主角设定。名讳：【${fd.name}】，${fd.gender}性，骨龄约${fd.age}岁。\n`;
            desc += `归属界域为【${fd.faction}】，本源种族为【${fd.race}】，现世身份是【${fd.identity}】。\n`;

            if(fd.affiliationFaction) {
                desc += `宗族/门派归属：${fd.affiliationFaction}${fd.affiliationRole ? '，所处席位为【' + fd.affiliationRole + '】' : ''}。\n`;
            }

            if(fd.bgTone && fd.bgTone.length > 0) {
                desc += `其所经历的物语基调为：${fd.bgTone.join('、')}。\n`;
            }

            if(fd.personality || fd.hobby) {
                desc += `其心性${fd.personality ? fd.personality : "未知"}，执念或偏好于${fd.hobby ? fd.hobby : "未知事物"}。\n`;
            }

            // 言语风貌
            let speechDesc = "";
            if (fd.speechTone && fd.speechTone.length > 0) speechDesc += `口吻风貌多为${fd.speechTone.join('、')}；`;
            if (fd.speechHabit && fd.speechHabit.length > 0) speechDesc += `言语习惯上${fd.speechHabit.join('、')}；`;
            if (fd.catchphrase) speechDesc += `常用口头禅是“${fd.catchphrase}”；`;
            if (fd.addressHabit) speechDesc += `称呼他人时${fd.addressHabit}；`;
            if (speechDesc) desc += `言辞之鉴：${speechDesc}\n`;
            if (fd.samples && fd.samples.length > 0) {
                desc += `典型语录：\n`;
                fd.samples.forEach(s => {
                    desc += `  - [${s.scene}] “${s.line}”\n`;
                });
            }

            // 外貌与衣冠
            if(fd.charDesc) {
                desc += `形神皮囊（绘卷全貌）：${fd.charDesc}\n`;
            } else {
                let appearDesc = [];
                if (fd.height || fd.weight || (fd.bodyType && fd.bodyType.length > 0)) {
                    let build = [];
                    if (fd.height) build.push(`身长${fd.height}cm`);
                    if (fd.weight) build.push(`体量${fd.weight}kg`);
                    if (fd.bodyType && fd.bodyType.length > 0) build.push(`体魄${fd.bodyType.join('、')}`);
                    appearDesc.push(build.join('，'));
                }
                if (fd.hairColor && fd.hairColor.length > 0 || fd.hairStyle && fd.hairStyle.length > 0) {
                    appearDesc.push(`留着${(fd.hairColor||[]).join('或')||"未知颜色"}的${(fd.hairStyle||[]).join('与')||"长发"}`);
                }
                if (fd.eyeColor && fd.eyeColor.length > 0 || fd.faceAura && fd.faceAura.length > 0) {
                    appearDesc.push(`生有${(fd.eyeColor||[]).join('或')||"双目"}，神采${(fd.faceAura||[]).join('且')||"独特"}`);
                }
                if (fd.specialMarks && fd.specialMarks.length > 0) {
                    appearDesc.push(`身上带有${fd.specialMarks.join('、')}等异相`);
                }
                if (appearDesc.length > 0) desc += `躯壳特征：${appearDesc.join('。')}。${fd.appearExtra ? fd.appearExtra : ''}\n`;

                let outfitDesc = [];
                if (fd.outfitTop) outfitDesc.push(`上装为${fd.outfitTop}`);
                if (fd.outfitBottom) outfitDesc.push(`下装为${fd.outfitBottom}`);
                if (fd.outfitShoes) outfitDesc.push(`足踏${fd.outfitShoes}`);
                if (fd.outfitAcc) outfitDesc.push(`随身佩戴${fd.outfitAcc}`);
                if (fd.outfitColor) outfitDesc.push(`整体主色调偏向${fd.outfitColor}`);
                if (outfitDesc.length > 0) desc += `衣冠配饰：${outfitDesc.join('，')}。${fd.outfitExtra ? fd.outfitExtra : ''}\n`;
            }

            if(fd.generatedBg) {
                desc += `前尘往事与背景：${fd.generatedBg}\n`;
            }

            desc += `\n该生灵作为【${fd.arrivalType}】，降临于【${fd.timeNode}】的【${fd.locCustom}】。\n`;
            if(fd.specialReq) {
                desc += `身上背负的天命旨意（初始遭遇）：${fd.specialReq}\n`;
            }
        }
        return desc;
    }

    function openExportPanel(idx) {
        _exportIdx = idx;
        var blob = new Blob([JSON.stringify(loadedProfiles[idx].data,null,2)],{type:'application/json'});
        var a = document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=(loadedProfiles[idx].displayName||'角色档案')+'.json'; a.click(); URL.revokeObjectURL(a.href);
    }
    function closeExportPanel() { document.getElementById('exportOverlay').classList.remove('open'); _exportIdx=-1; }
    function confirmExport() { closeExportPanel(); }

    function importProfile(event) {
        var file=event.target.files[0]; if(!file)return;
        var reader=new FileReader();
        reader.onload=function(e){
            try{
                var data=JSON.parse(e.target.result);
                if(!data.name && !data.canonName) data.name = file.name.replace(/\.json$/i,'') || '导入的卷宗';
                restoreFormData(data); maxStepReached=activeSteps.length-1; showPane('preview');
            }catch(ex){toast('t-home','导入失败：残卷格式损坏','err');}
        };
        reader.readAsText(file); event.target.value='';
    }

    function saveDraft() {try { var fd = collectFormData(); fd._paneId = curPaneId; fd._maxStep = maxStepReached; localStorage.setItem(DRAFT_KEY, JSON.stringify(fd)); } catch(e) {}}
    function checkDraft() {try { var s = localStorage.getItem(DRAFT_KEY); if (!s) return;var d = JSON.parse(s); if (!d || (!d.name && !d.canonName)) return;var dName=getDisplayName(d);var area = document.getElementById('draftBannerArea');area.innerHTML = '<div class="draft-banner"><p>发现未落印的残卷：[ <strong>' + escHtml(dName) + '</strong> ]</p><div><button class="draft-banner-btn" style="color:var(--red);border-color:var(--red)" onclick="restoreDraft()">继续研墨</button> <button class="draft-banner-btn" onclick="discardDraft()">焚毁</button></div></div>'; } catch(e) {}}
    function restoreDraft() {try { var s = localStorage.getItem(DRAFT_KEY); if (!s) return;var d = JSON.parse(s); restoreFormData(d); maxStepReached = d._maxStep || 1;var targetPane = (d._paneId) || 'roletype';showPane(targetPane); } catch(e) {}document.getElementById('draftBannerArea').innerHTML = '';}
    function discardDraft() { localStorage.removeItem(DRAFT_KEY); document.getElementById('draftBannerArea').innerHTML = ''; }
    function clearDraft() { localStorage.removeItem(DRAFT_KEY); }

    async function loadProfiles() {
        var recentEl=document.getElementById('recentList');
        if(recentEl) recentEl.innerHTML='<div style="text-align:center;color:var(--ink-light);padding:30px;">正在查阅世界书...</div>';

        try { loadedProfiles = JSON.parse(localStorage.getItem('hyakumonogatari_recent_profiles') || '[]'); } catch(e) { loadedProfiles = []; }
        loadedProfiles.sort(function(a,b){var ta=(a.data&&a.data._savedAt)||0;var tb=(b.data&&b.data._savedAt)||0;return tb-ta;});
        renderRecentProfiles();
    }

    function renderRecentProfiles() {
        var recentEl=document.getElementById('recentList'); if(!recentEl)return;
        var listEl = document.getElementById('profileList');

        if(loadedProfiles.length===0){
            recentEl.innerHTML='<div style="text-align:center;color:var(--ink-light);padding:30px;">书库空空如也...</div>';
            if(listEl) listEl.innerHTML='';
            return;
        }

        var show=loadedProfiles.slice(0,3); var h='';
        show.forEach(function(p){
            var realIdx=loadedProfiles.indexOf(p);
            h+='<div class="recent-card" onclick="editProfile('+realIdx+')"><div style="flex:1">';
            h+='<span class="recent-card-name">' + escHtml(p.displayName) + '</span>';
            var tDesc = p.data.roleType === 'canon' ? '原著存在' : ('阵营: ' + escHtml(p.data.faction||'未知') + ' | 种族: ' + escHtml(p.data.race||'未知'));
            h+='<div class="profile-card-detail">' + tDesc + '</div></div>';
            h+='<button class="profile-action-btn">展卷</button></div>';
        });
        recentEl.innerHTML=h;

        if(!listEl) return;
        var lh='';
        loadedProfiles.forEach(function(p, idx) {
            lh += '<div class="profile-card"><div style="flex:1">';
            lh += '<span class="profile-card-name">' + escHtml(p.displayName) + '</span>';
            lh += '<div class="profile-card-detail">落印于: ' + new Date(p.data._savedAt || Date.now()).toLocaleString() + '</div></div>';
            lh += '<div style="display:flex;gap:5px;">';
            lh += '<button class="profile-action-btn" onclick="event.stopPropagation();editProfile('+idx+')">涂改</button>';
            lh += '<button class="profile-action-btn" onclick="event.stopPropagation();openExportPanel('+idx+')">誊写</button>';
            lh += '<button class="profile-action-btn danger" onclick="event.stopPropagation();deleteProfile('+idx+')">焚毁</button>';
            lh += '</div></div>';
        });
        listEl.innerHTML = lh;
    }

    function editProfile(idx) {
        var p = loadedProfiles[idx];
        if(!p) return;
        restoreFormData(p.data);
        maxStepReached = activeSteps.length - 1;
        showPane('preview');
    }

    async function deleteProfile(idx) {
        if(!confirm('警告：确定要将此卷宗从本地记录和世界书中焚毁吗？')) return;
        var p = loadedProfiles[idx];

        try {
            var delApi = getApi('deleteWorldbookEntries');
            if (delApi && p.uid) { await delApi(getWorldbookName(), [p.uid]); }
        } catch(e) {}

        loadedProfiles.splice(idx, 1);
        localStorage.setItem('hyakumonogatari_recent_profiles', JSON.stringify(loadedProfiles));

        await loadProfiles();
        toast('t-home', '案卷已焚毁', 'ok');
    }

