    function closeSettings(){document.getElementById('settingsOverlay').classList.remove('open');}

    function sendStartTrigger(fd) {
        var triggerFn = getApi('triggerSlash');
        if (!triggerFn) return;

        let prompt = `【系统指令：平安百物语落印开局】\\n`;
        prompt += `请基于《阴阳师》的世界观，根据以下设定展开一段开局剧情。\\n`;
        prompt += `**变量更新要求 (必须严格执行)\n请根据全局提示词中定义的【变量更新规则】（包含世界、主角、人际关系、势力关系），在回复末尾输出 JSON Patch 命令以初始化变量。\n特别强调：你必须根据角色的界域和身份，初始化对应的【势力关系】；根据开场遇到的人物，初始化【人际关系】！**\\n\\n`;

        if (fd.gameMode === 'game') {
            prompt += `【当前处于游戏模式】：请务必在开局剧情中通过事件为主角发放一定数量的“召唤符咒”。\\n\\n`;
        }

        if(fd.roleType === 'canon') {
            prompt += `## 核心设定\\n`;
            prompt += `- 扮演角色：【${fd.canonName}】 (原著存在)\\n\\n`;
        } else {
            const name = fd.name || '无名氏';
            const ageNum = parseInt(fd.age) || 0;
            const gender = fd.gender || '男';
            const looks = fd.charDesc || '未详细描述，请自由发挥';
            const faction = fd.faction || '平安京';
            const race = fd.race || '人类';
            const identity = fd.identity || '平民';

            prompt += `## 核心设定 (自定义)\\n`;
            prompt += `- 名讳：${name}\\n`;
            prompt += `- 阴阳骨龄：${gender} \ ${ageNum}岁\\n`;
            prompt += `- 形神皮囊：${looks}\\n`;
            prompt += `- 归属界域：${faction}\\n`;
            prompt += `- 本源种族：${race}\\n`;
            prompt += `- 现世身份：${identity}\\n\\n`;
        }

        const loc = fd.locCustom || '未知地点';
        const time = fd.timeNode || '未知时间';
        const special = fd.specialReq || '';

        prompt += `## 时空降临\\n`;
        prompt += `- 降临时间：${time}\\n`;
        prompt += `- 初始落足点：${loc}\\n\\n`;

        if (special) {
            prompt += `## 天命旨意（剧情必须遵循）\\n${special}\\n\\n`;
        } else {
            prompt += `## 剧情要求\\n请结合上述设定，描写一段具有和风志异氛围的开场。包含具体的情境、动作和感官细节。\\n\\n`;
        }

        prompt += `## 变量更新要求 (必须严格执行)\\n`;
        prompt += `请根据全局提示词中定义的【变量更新规则】（包含世界、主角、人际关系、势力关系），在回复末尾输出 JSON Patch 命令以初始化变量。\\n`;
        prompt += `**特别强调：你必须根据角色的界域和身份，初始化对应的【势力关系】；根据开场遇到的人物，初始化【人际关系】！**\\n\\n`;

        prompt += `\`\`\`xml\\n`;
        prompt += `\\n`;
        prompt += `\`\`\``;

        triggerFn('/send ' + prompt + ' | /trigger');
    }

    async function saveToWorldbook() {
        var btn = document.getElementById('btn-save-wb');
        if (btn) { btn.disabled = true; btn.innerHTML = '正在结契...'; }

        try {
            var fd = collectFormData();
            var wbName = getWorldbookName();
            var entryName = '[角色档案]' + getDisplayName(fd);
            fd._savedAt = Date.now();

            var content = generateNaturalDesc(fd);

            var createEntryApi = getApi('createWorldbookEntries');
            var updateEntryApi = getApi('updateWorldbookEntries');

            if (!createEntryApi && !updateEntryApi) {
                toast('t-preview', '已在本地落印 (未连接至藏书阁)', 'ok');
            } else {
                var getWbApi = getApi('getWorldbook');
                var realUid = null;
                if(getWbApi){
                    var entries = await getWbApi(wbName);
                    if(entries && entries.length > 0){
                        var existingEntry = entries.find(function(e) { return e.name === entryName; });
                        if(existingEntry) realUid = existingEntry.uid;
                    }
                }

                if (realUid !== null && updateEntryApi) {
                    await updateEntryApi(wbName, [{ uid: realUid, name: entryName, content: content }]);
                    fd.uid = realUid;
                    toast('t-preview', '旧卷已更新', 'ok');
                } else if (createEntryApi) {
                    var newEntries = await createEntryApi(wbName, [{
                        name: entryName,
                        content: content,
                        enabled: true,
                        position: { type: "after_character_definition", order: 100 },
                        strategy: { type: "constant", keys: [] }
                    }]);
                    if(newEntries && newEntries.length > 0) fd.uid = newEntries[0].uid;
                    toast('t-preview', '新卷已收入藏书阁', 'ok');
                }
            }

            var localProfiles = JSON.parse(localStorage.getItem('hyakumonogatari_recent_profiles') || '[]');
            var existingIdx = localProfiles.findIndex(function(p) { return p.name === entryName; });
            if (existingIdx >= 0) {
                localProfiles[existingIdx] = {uid: fd.uid, name: entryName, displayName: getDisplayName(fd), data: fd};
            } else {
                localProfiles.unshift({uid: fd.uid, name: entryName, displayName: getDisplayName(fd), data: fd});
            }
            if (localProfiles.length > 20) localProfiles = localProfiles.slice(0, 20);
            localStorage.setItem('hyakumonogatari_recent_profiles', JSON.stringify(localProfiles));

            // ====== MVU 变量强制写入 ======
            try {
                if (typeof waitGlobalInitialized === 'function' && typeof Mvu !== 'undefined') {
                    await waitGlobalInitialized('Mvu');
                    // 优先获取最新楼层变量，如果没有则获取chat级变量
                    var mvuData = Mvu.getMvuData({type:'message', message_id:'latest'});
                    if (!mvuData) {
                        mvuData = Mvu.getMvuData({type:'chat'});
                    }

                    if (mvuData && typeof _ !== 'undefined') {
                        var isGame = (fd.gameMode === 'game');
                        var isOnmyoji = (isGame || fd.identity === '阴阳师');

                        // 确保对象结构存在
                        if (!mvuData.stat_data) mvuData.stat_data = {};
                        if (!mvuData.stat_data.主角) mvuData.stat_data.主角 = {};

                        // 正确写入主角目录下
                        _.set(mvuData, 'stat_data.主角.是否为游戏模式', isGame);
                        _.set(mvuData, 'stat_data.主角.是否为阴阳师', isOnmyoji);

                        // 覆盖最新楼层
                        await Mvu.replaceMvuData(mvuData, {type:'message', message_id:'latest'});
                        // 为了保险起见，也更新一次chat级别
                        await Mvu.replaceMvuData(mvuData, {type:'chat'});
                    }
                }
            } catch(err) {
                console.error("MVU变量更新失败", err);
            }
            // ==============================

            clearDraft();
            await loadProfiles();
            sendStartTrigger(fd);

            setTimeout(function() { showPane('home'); }, 1500);

        } catch (e) {
            console.error('结契失败:', e);
            toast('t-preview', '错误: ' + e.message, 'err');
        } finally {
            if (btn) { btn.disabled = false; btn.innerHTML = '确立因果 · 开启世界'; }
        }
    }

    function startAutoSave() {if (_autoSaveTimer) return;_autoSaveTimer = setInterval(function() {if (curPaneId !== 'home') { saveDraft(); }}, 30000);}
    window.onload = function() {
        buildTagGroup('bodyTypeTags', BODY_TYPES, true);
        buildTagGroup('hairStyleTags', HAIR_STYLES, true);
        buildTagGroup('faceAuraTags', FACE_AURA, false);
        buildTagGroup('speechToneTags', SPEECH_TONE, false);
        buildTagGroup('speechHabitTags', SPEECH_HABIT, false);

        loadApiConfig();
        loadProfiles().then(function(){
            checkDraft();
            showPane('home');
            startAutoSave();
        });
    };
</script>
