      const container = document.getElementById("map-container");
      const mapWorld = document.getElementById("map-world");
      const tooltip = document.getElementById("tooltip");
      const searchInput = document.getElementById("search-input");
      const searchResults = document.getElementById("search-results");
      const zoomIndicator = document.getElementById("zoom-indicator");

      const MAP_W = 1536;
      const MAP_H = 1075;
      let scale = 0.5;
      let panX = 0;
      let panY = 0;
      let isDragging = false;
      let hasDragged = false;
      let startX, startY;
      let dragStartClientX = 0, dragStartClientY = 0;
      let lastTouchDist = 0;
      const DRAG_THRESHOLD = 5;

      function updateTransform() {
        mapWorld.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
        zoomIndicator.textContent = Math.round(scale * 100) + "%";
      }

      function getContainerSize() {
        const rect = container.getBoundingClientRect();
        return { width: rect.width, height: rect.height };
      }

      function zoomIn() { scale = Math.min(scale * 1.3, 2.5); updateTransform(); }
      function zoomOut() { scale = Math.max(scale / 1.3, 0.3); updateTransform(); }
      function resetView() {
        const size = getContainerSize();
        const scaleX = size.width / MAP_W;
        const scaleY = size.height / MAP_H;
        scale = Math.min(scaleX, scaleY) * 0.95;
        panX = (size.width - MAP_W * scale) / 2;
        panY = (size.height - MAP_H * scale) / 2;
        updateTransform();
      }

      container.addEventListener("mousedown", (e) => {
        if (e.target.closest("#controls, #search-bar, #search-results, #info-panel")) return;
        isDragging = true; hasDragged = false;
        startX = e.clientX - panX; startY = e.clientY - panY;
        dragStartClientX = e.clientX; dragStartClientY = e.clientY;
        container.classList.add("dragging");
      });

      window.addEventListener("mousemove", (e) => {
        if (!isDragging) return;
        const dx = e.clientX - dragStartClientX; const dy = e.clientY - dragStartClientY;
        if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) hasDragged = true;
        panX = e.clientX - startX; panY = e.clientY - startY;
        updateTransform();
      });

      window.addEventListener("mouseup", () => {
        isDragging = false; container.classList.remove("dragging");
        setTimeout(() => { hasDragged = false; }, 0);
      });

      container.addEventListener("wheel", (e) => {
        e.preventDefault();
        const rect = container.getBoundingClientRect();
        const mouseX = e.clientX - rect.left; const mouseY = e.clientY - rect.top;
        const oldScale = scale;
        if (e.deltaY < 0) scale = Math.min(scale * 1.15, 2.5); else scale = Math.max(scale / 1.15, 0.3);
        panX = mouseX - (mouseX - panX) * (scale / oldScale);
        panY = mouseY - (mouseY - panY) * (scale / oldScale);
        updateTransform();
      }, { passive: false });

      container.addEventListener("touchstart", (e) => {
        if (e.target.closest("#controls, #search-bar, #search-results, #info-panel")) return;
        if (e.touches.length === 1) {
          isDragging = true; hasDragged = false;
          startX = e.touches[0].clientX - panX; startY = e.touches[0].clientY - panY;
          dragStartClientX = e.touches[0].clientX; dragStartClientY = e.touches[0].clientY;
        } else if (e.touches.length === 2) {
          isDragging = false;
          const dx = e.touches[0].clientX - e.touches[1].clientX;
          const dy = e.touches[0].clientY - e.touches[1].clientY;
          lastTouchDist = Math.sqrt(dx * dx + dy * dy);
        }
      }, { passive: false });

      container.addEventListener("touchmove", (e) => {
        e.preventDefault();
        if (e.touches.length === 1 && isDragging) {
          const dx = e.touches[0].clientX - dragStartClientX; const dy = e.touches[0].clientY - dragStartClientY;
          if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) hasDragged = true;
          panX = e.touches[0].clientX - startX; panY = e.touches[0].clientY - startY;
          updateTransform();
