        marker.addEventListener("mouseleave", () => { tooltip.classList.remove("show"); });
      });

      function showPanel(data) {
        document.getElementById("panel-title").textContent = data.name;
        let html = "";
        html += `<span class="info-tag" style="color:${data.tagColor}; border-color:${data.tagColor}">${data.type} · ${data.region}</span>`;
        html += `<div class="info-section"><h3>界域概述</h3><p>${data.desc}</p></div>`;
        if (data.location) html += `<div class="info-section"><h3>所在方位</h3><p>${data.location}</p></div>`;
        if (data.features && data.features.length > 0) html += `<div class="info-section"><h3>风貌特征</h3><ul>${data.features.map((f) => `<li>${f}</li>`).join("")}</ul></div>`;
        if (data.places && data.places.length > 0) html += `<div class="info-section"><h3>核心地界</h3><ul>${data.places.map((p) => `<li>${p}</li>`).join("")}</ul></div>`;
        if (data.characters && data.characters.length > 0) html += `<div class="info-section"><h3>名号人物</h3><div class="info-characters">${data.characters.map((c) => `<span class="char-badge">${c.name}<span class="char-role">${c.role}</span></span>`).join("")}</div></div>`;
        if (data.resources) html += `<div class="info-section"><h3>秘传异宝</h3><p>${data.resources}</p></div>`;
        document.getElementById("panel-body").innerHTML = html;
        document.getElementById("info-panel").classList.add("show");
        document.getElementById("overlay").classList.add("show");
      }

      function closePanel() {
        document.getElementById("info-panel").classList.remove("show");
        document.getElementById("overlay").classList.remove("show");
      }

      searchInput.addEventListener("input", () => {
        const query = searchInput.value.trim().toLowerCase();
        if (!query) { searchResults.style.display = "none"; return; }
        const results = [];
        for (const [id, data] of Object.entries(locationData)) {
          if (data.name.toLowerCase().includes(query) || data.region.toLowerCase().includes(query) || data.type.toLowerCase().includes(query) || (data.characters && data.characters.some((c) => c.name.toLowerCase().includes(query)))) {
            results.push({ id, data });
          }
        }
        if (results.length === 0) {
          searchResults.innerHTML = '<div class="result-item" style="color:#7a6e5d">未寻得此界...</div>';
        } else {
          searchResults.innerHTML = results.slice(0, 10).map((r) => `<div class="result-item" data-id="${r.id}">${r.data.name}<span class="result-region">${r.data.region}</span></div>`).join("");
        }
        searchResults.style.display = "block";
      });

      searchResults.addEventListener("click", (e) => {
        const item = e.target.closest(".result-item");
        if (item && item.dataset.id) {
          const id = item.dataset.id; const data = locationData[id];
          if (data) {
            showPanel(data); searchResults.style.display = "none"; searchInput.value = "";
            const marker = document.querySelector(`.marker[data-id="${id}"]`);
            if (marker) {
              const left = parseFloat(marker.style.left) / 100 * MAP_W; const top = parseFloat(marker.style.top) / 100 * MAP_H;
              const size = getContainerSize(); scale = 1.2;
              panX = size.width / 2 - left * scale; panY = size.height / 2 - top * scale;
              updateTransform();
            }
          }
        }
      });

      document.addEventListener("click", (e) => { if (!e.target.closest("#search-bar, #search-results")) searchResults.style.display = "none"; });
      document.addEventListener("keydown", (e) => { if (e.key === "Escape") { closePanel(); searchResults.style.display = "none"; } });

      resetView();

      // 优化酒馆容器高度适配
      if (typeof ResizeObserver !=='undefined') {
        new ResizeObserver(() => {
          if(container.parentElement) {
            // 如果父容器高度有效且大于某个值，则使用父容器高度，否则保持自身固定高度
            const parentHeight = container.parentElement.clientHeight;
            if(parentHeight > 400) {
               container.style.height = parentHeight + 'px';
            }
          }
        }).observe(container.parentElement || document.body);
      }
    </script>
  </body>
