            background: linear-gradient(to top, rgba(10,5,20,0.95) 0%, rgba(15,10,25,0.7) 40%, transparent 100%);
            display: flex; flex-direction: column; align-items: center; gap: 15px;
        }
        /* 控制区顶部光晕 */
        .controls-overlay::before {
            content: ''; position: absolute; top: 0; left: 20%; right: 20%; height: 1px;
            background: radial-gradient(circle, rgba(212,175,55,0.4) 0%, transparent 80%);
        }
        .controls-overlay > * { pointer-events: auto; }
        .amulet-display { font-size: 15px; color: var(--text-sub); text-shadow: 0 2px 4px #000; letter-spacing: 1px; }
        .amulet-display span { font-size: 22px; font-weight: bold; color: var(--gold); text-shadow: 0 0 10px rgba(212,175,55,0.8); margin: 0 8px; font-family: "Georgia", serif; }

        /* 祈愿刻度盘 */
        .summon-count-selector {
            display: flex; align-items: center; gap: 15px; background: rgba(20, 15, 30, 0.8); border: 1px solid var(--border-color);
            border-radius: 30px; padding: 5px 15px; box-shadow: 0 5px 15px rgba(0,0,0,0.6), inset 0 0 10px rgba(212,175,55,0.1); backdrop-filter: blur(5px);
            position: relative; overflow: hidden;
        }
        .summon-count-selector::after {
            content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
            background: conic-gradient(transparent, rgba(212,175,55,0.1), transparent 30%);
            animation: spin-inf 4s linear infinite; pointer-events: none;
        }
        .count-btn { background: transparent; border: none; color: var(--gold); font-size: 24px; font-weight: bold; cursor: pointer; width: 30px; height: 30px; display: flex; justify-content: center; align-items: center; border-radius: 50%; transition: var(--transition); text-shadow: 0 0 8px rgba(212,175,55,0.5); z-index: 2; }
        .count-btn:hover:not(:disabled) { background: rgba(212,175,55,0.15); box-shadow: 0 0 10px rgba(212,175,55,0.3); }
        .count-btn:disabled { color: #555; cursor: default; text-shadow: none; }
        .count-display { display: flex; align-items: baseline; gap: 6px; z-index: 2; }
        .count-label { font-size: 13px; color: var(--text-sub); letter-spacing: 2px; }
        .count-number { font-size: 20px; font-weight: bold; color: #fff; text-shadow: 0 0 10px var(--gold); width: 24px; text-align: center; }

        /* === 独立设置模态窗 === */
        .modal-bg { position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.85); backdrop-filter: blur(6px); z-index: 100; display: none; justify-content: center; align-items: center; opacity: 0; transition: opacity 0.3s ease; pointer-events: none; }
        .modal-bg.active { display: flex; opacity: 1; pointer-events: auto; }
        .settings-modal {
            background: rgba(25, 20, 35, 0.95); border: 1px solid var(--gold); border-radius: 8px; width: 90%; max-width: 450px;
            max-height: 90vh; overflow-y: auto; padding: 25px; box-shadow: 0 0 40px rgba(0,0,0,0.9), inset 0 0 20px rgba(212,175,55,0.15); transform: scale(0.95); transition: transform 0.3s ease;
        }
        .settings-modal::-webkit-scrollbar { width: 6px; }
        .settings-modal::-webkit-scrollbar-track { background: transparent; }
        .settings-modal::-webkit-scrollbar-thumb { background: rgba(212,175,55,0.3); border-radius: 3px; }
        .settings-modal::-webkit-scrollbar-thumb:hover { background: rgba(212,175,55,0.6); }

        .modal-bg.active .settings-modal { transform: scale(1); }
        .modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; border-bottom: 1px dashed var(--border-color); padding-bottom: 15px; }
        .modal-header h2 { font-size: 18px; color: var(--gold); letter-spacing: 2px; }
        .btn-close { background: none; border: none; color: var(--text-sub); font-size: 24px; cursor: pointer; transition: color 0.3s; }
        .btn-close:hover { color: #ff6b6b; }
        .form-group { margin-bottom: 18px; }
        .form-label { display: block; font-size: 13px; color: var(--gold); margin-bottom: 8px; letter-spacing: 1px; }
        .form-input, .form-select { width: 100%; padding: 10px 12px; font-size: 13px; background: rgba(10,5,15,0.8); border: 1px solid var(--border-color); color: var(--text-main); border-radius: 4px; transition: var(--transition); }
        .form-input:focus, .form-select:focus { border-color: var(--gold); outline: none; box-shadow: 0 0 8px rgba(212,175,55,0.2); }
        .form-select option { background: #191423; }
        .input-group { display: flex; gap: 8px; }
        .btn-action { background: rgba(40,30,50,0.8); border: 1px solid var(--border-color); color: var(--text-main); padding: 8px 15px; border-radius: 4px; cursor: pointer; font-size: 12px; white-space: nowrap; transition: var(--transition); letter-spacing: 1px; }
        .btn-action:hover { border-color: var(--gold); color: var(--gold); box-shadow: 0 0 8px rgba(212,175,55,0.3); }
        .btn-save { width: 100%; background: rgba(212,175,55,0.05); border: 1px solid var(--gold); color: var(--gold); padding: 12px; font-size: 15px; border-radius: 4px; cursor: pointer; margin-top: 15px; transition: var(--transition); letter-spacing: 2px; font-weight: bold; }
        .btn-save:hover { background: rgba(212,175,55,0.2); box-shadow: 0 0 15px rgba(212,175,55,0.4); }

        /* === 结果展示浮层 === */
        .result-overlay {
            position: absolute; top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(15, 10, 25, 0.95); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
            z-index: 50; display: none; flex-direction: column; padding: 20px; overflow-y: auto; perspective: 1000px;
        }
        .result-overlay.active { display: flex; animation: fadeIn 0.4s ease; }

        .ssr-flash { position: absolute; top:0; left:0; right:0; bottom:0; z-index: 45; pointer-events: none; background: radial-gradient(circle, rgba(255,50,0,0.4) 0%, rgba(212,175,55,0.2) 50%, transparent 100%); opacity: 0; display: none; mix-blend-mode: screen; }
        .ssr-flash.active { display: block; animation: godFlash 2s cubic-bezier(0.1, 0.8, 0.1, 1) forwards; }
        @keyframes godFlash { 0% { opacity: 1; transform: scale(1); background: #fff; } 20% { opacity: 0.8; background: var(--ssr-color); transform: scale(1.1); } 100% { opacity: 0; transform: scale(1.5); } }

        .result-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; flex-shrink: 0; border-bottom: 1px solid rgba(212,175,55,0.3); padding-bottom: 15px; z-index: 51; }
        .result-header h2 { color: var(--gold); font-size: 20px; letter-spacing: 3px; text-shadow: 0 0 15px rgba(212,175,55,0.6); }
        .result-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 18px; padding-bottom: 20px; z-index: 51; }

        /* 卡牌样式 */
        .shikigami-card { background: rgba(30,20,40,0.85); border: 1px solid var(--border-color); border-radius: 8px; padding: 18px; border-left: 4px solid var(--text-sub); display: flex; flex-direction: column; transition: var(--transition); opacity: 0; transform-style: preserve-3d; }
        .shikigami-card.flip-in { animation: cardFlipIn 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
        @keyframes cardFlipIn { 0% { opacity: 0; transform: rotateY(-90deg) translateZ(100px) scale(0.8); } 100% { opacity: 1; transform: rotateY(0deg) translateZ(0) scale(1); } }
        .shikigami-card:hover { background: rgba(40,30,55,0.95); box-shadow: 0 6px 20px rgba(0,0,0,0.8), 0 0 15px rgba(212,175,55,0.3); border-color: var(--gold); transform: translateY(-5px) scale(1.02); z-index: 10; }
        .card-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; border-bottom: 1px dashed rgba(255,255,255,0.15); padding-bottom: 8px; }
        .card-name { font-size: 18px; font-weight: bold; color: #fff; letter-spacing: 1px; }
        .card-rarity { font-size: 16px; font-weight: bold; font-style: italic; }
        .card-sub { font-size: 12px; color: var(--text-sub); margin-bottom: 8px; }
        .card-desc { font-size: 13px; line-height: 1.5; color: #d0c0c8; margin-bottom: 12px; flex: 1; }
        .card-skills { background: rgba(10,5,15,0.6); padding: 8px 10px; border-radius: 6px; margin-bottom: 15px; border: 1px solid rgba(255,255,255,0.05); }
        .skill-item { font-size: 12px; margin-bottom: 4px; line-height: 1.4; }
        .skill-name { color: var(--gold); font-weight: bold; }
        .btn-bind { width: 100%; background: transparent; border: 1px solid var(--gold); color: var(--gold); padding: 8px; font-size: 13px; border-radius: 4px; cursor: pointer; transition: var(--transition); letter-spacing: 1px; position: relative; overflow: hidden; }
        .btn-bind::after { content:''; position:absolute; top:0; left:-100%; width:50%; height:100%; background: linear-gradient(90deg, transparent, rgba(212,175,55,0.4), transparent); transform: skewX(-20deg); transition: 0s; }
        .btn-bind:hover:not(:disabled) { background: rgba(212,175,55,0.2); box-shadow: 0 0 10px rgba(212,175,55,0.3); }
        .btn-bind:hover:not(:disabled)::after { animation: shine 0.6s; }
        @keyframes shine { 100% { left: 200%; } }
        .btn-bind:disabled { border-color: #444; color: #666; cursor: default; background: rgba(0,0,0,0.3); box-shadow: none; }

        .rarity-SP { border-left-color: var(--ssr-color); box-shadow: 0 0 15px rgba(255,50,0,0.15) inset; } .rarity-SP .card-rarity { color: var(--ssr-color); text-shadow: 0 0 10px rgba(255,50,0,0.8); }
        .rarity-SSR { border-left-color: var(--ssr-color); box-shadow: 0 0 15px rgba(255,50,0,0.15) inset; } .rarity-SSR .card-rarity { color: var(--ssr-color); text-shadow: 0 0 10px rgba(255,50,0,0.8); }
        .rarity-SR { border-left-color: var(--sr-color); } .rarity-SR .card-rarity { color: var(--sr-color); text-shadow: 0 0 5px rgba(216,182,255,0.4); }
        .rarity-R { border-left-color: var(--r-color); } .rarity-R .card-rarity { color: var(--r-color); }
        .rarity-N { border-left-color: var(--n-color); } .rarity-N .card-rarity { color: var(--n-color); }

        .status-msg { position: absolute; top: 90px; left: 50%; transform: translateX(-50%); background: rgba(15,10,25,0.95); padding: 12px 25px; border-radius: 30px; font-size: 15px; z-index: 60; opacity: 0; transition: opacity 0.3s; pointer-events: none; border: 1px solid var(--border-color); backdrop-filter: blur(5px); box-shadow: 0 6px 25px rgba(0,0,0,0.9); text-align: center; max-width: 80%; word-break: break-all; letter-spacing: 1px; }
        .status-msg.active { opacity: 1; }
        .status-msg.error { color: #ff6b6b; border-color: #5a2020; box-shadow: 0 0 15px rgba(255,107,107,0.2); }
        .status-msg.success { color: var(--gold); border-color: var(--gold); box-shadow: 0 0 15px rgba(212,175,55,0.2); }
        .status-msg.loading { color: var(--gold-bright); animation: pulse 1.5s infinite; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }

        /* ==========================================
           手机端极致压缩优化
           ========================================== */
        @media (max-width: 600px) {
            .app-header { padding: 10px 15px; }
            .header-title h1 { font-size: 16px; letter-spacing: 2px; }
            .btn-icon { padding: 4px 10px; font-size: 11px; }

            .controls-overlay { padding: 15px 10px; gap: 10px; }
            .amulet-display { font-size: 13px; }
            .amulet-display span { font-size: 18px; margin: 0 5px; }
            .summon-count-selector { padding: 4px 12px; gap: 10px; }
            .count-btn { width: 26px; height: 26px; font-size: 20px; }
            .count-number { font-size: 18px; width: 20px; }

            .result-overlay { padding: 10px; }
            .result-header { margin-bottom: 12px; padding-bottom: 10px; }
            .result-header h2 { font-size: 16px; letter-spacing: 2px; }

            .result-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; padding-bottom: 10px; }

            .shikigami-card { padding: 10px; border-left-width: 3px; border-radius: 6px; }
            .card-head { margin-bottom: 6px; padding-bottom: 6px; }
            .card-name { font-size: 14px; letter-spacing: 0; }
            .card-rarity { font-size: 13px; }
            .card-sub { font-size: 10px; margin-bottom: 6px; }
            .card-desc { font-size: 11px; line-height: 1.35; margin-bottom: 8px; }

            .card-skills { padding: 6px; margin-bottom: 10px; border-radius: 4px; }
            .skill-item { font-size: 10px; margin-bottom: 3px; }

            .btn-bind { padding: 6px; font-size: 11px; }
            .status-msg { top: 70px; padding: 10px 15px; font-size: 13px; border-radius: 20px; }
            .corner-deco { width: 40px; height: 40px; }
        }
    </style>

