                <div class="form-group"><label class="form-label">API 接口地址</label><input type="text" class="form-input" id="apiUrl" placeholder="https://api.openai.com/v1"></div>
                <div class="form-group"><label class="form-label">API 密钥 (Key)</label><input type="password" class="form-input" id="apiKey" placeholder="sk-..."></div>
                <div class="form-group">
                    <label class="form-label">模型名称 (Model)</label>
                    <div class="input-group">
                        <select class="form-select" id="apiModelSelect" style="display:none;"></select>
                        <input type="text" class="form-input" id="apiModel" placeholder="gpt-4o">
                        <button class="btn-action" id="btnFetchModels">获取模型</button>
                    </div>
                </div>
                <div class="form-group"><label class="form-label">最大回复长度 (Max Tokens)</label><input type="number" class="form-input" id="apiMaxTokens" placeholder="默认4000 (建议调大)" min="100" max="16000"></div>
            </div>
            <button class="btn-save" id="btnSaveConfig">保存配置</button>
        </div>
    </div>
</div>

<script type="module">
    import * as THREE from 'three';

    /* 全局燃烧状态控制 */
    let isBurning = false;
    let burnProgress = 0;
    let finalTalismanCanvas = null;

    /* ==========================================
       指尖幽火 (鼠标跟随)
       ========================================== */
    const cursorFire = document.getElementById('cursorFire');
    const appContainer = document.getElementById('appContainer');
    appContainer.addEventListener('mousemove', (e) => {
        const rect = appContainer.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        cursorFire.style.transform = `translate(${x}px, ${y}px)`;
    });

    /* ==========================================
       初始化五行法阵背景动画与樱花飘落
       ========================================== */
    (function initBackground() {
        const ring = document.getElementById('spellRing');
        const spells = ['臨','兵','闘','者','皆','陣','列','在','前'];
        spells.forEach((char, i) => {
            const angle = (i / spells.length) * 360;
            const span = document.createElement('span');
            span.className = 'spell-char';
            span.textContent = char;
            span.style.transform = `rotate(${angle}deg) translateY(-215px)`;
            ring.appendChild(span);
        });

        const starfield = document.getElementById('starfield');
        for (let i = 0; i < 30; i++) {
            const star = document.createElement('div');
            star.className = 'star';
            const size = Math.random() * 2 + 1;
            star.style.width = star.style.height = size + 'px';
            star.style.left = Math.random() * 100 + '%';
            star.style.top = Math.random() * 100 + '%';
            star.style.animationDelay = Math.random() * 3 + 's';
            star.style.boxShadow = `0 0 ${size*2}px ${size>1.5?'var(--gold-bright)':'var(--purple-bright)'}`;
            starfield.appendChild(star);
        }

        const ascending = document.getElementById('ascendingParticles');
        const colors = ['#d4af37', '#f0d060', '#e74c3c', '#b370d0'];
        for (let i = 0; i < 20; i++) {
            const p = document.createElement('div');
            p.className = 'ascend-particle';
            const size = Math.random() * 4 + 2;
            const color = colors[Math.floor(Math.random() * colors.length)];
            p.style.width = p.style.height = size + 'px';
            p.style.background = color;
            p.style.boxShadow = `0 0 ${size*3}px ${color}`;
            p.style.left = Math.random() * 100 + '%';
            p.style.bottom = -10 - Math.random() * 30 + 'px';
            p.style.animationDuration = Math.random() * 10 + 10 + 's';
            p.style.animationDelay = Math.random() * 12 + 's';
            ascending.appendChild(p);
        }

        const petalContainer = document.getElementById('petalContainer');
        for (let i = 0; i < 25; i++) {
            const petal = document.createElement('div');
            petal.className = 'petal';
            const size = Math.random() * 8 + 6;
            petal.style.width = size + 'px';
            petal.style.height = size + 'px';
            petal.style.left = Math.random() * 100 + '%';
            petal.style.animationDuration = (Math.random() * 5 + 5) + 's, ' + (Math.random() * 3 + 2) + 's';
            petal.style.animationDelay = (Math.random() * 5) + 's, ' + (Math.random() * 5) + 's';
            petalContainer.appendChild(petal);
        }
    })();

    /* ==========================================
       第一部分：Three.js 3D画符模块与灵力注入粒子系统
       ========================================== */
    const container = document.getElementById('talismanContainer');
    const canvas = document.getElementById('renderCanvas');
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });

    let cWidth = container.clientWidth;
    let cHeight = container.clientHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(cWidth, cHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.1;
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2('#0f0a12', 0.00005);

    const camera = new THREE.PerspectiveCamera(42, cWidth / cHeight, 0.5, 30);
    camera.position.set(1.5, 0.3, 7.8);
    camera.lookAt(0, -0.1, 0);

    scene.add(new THREE.AmbientLight('#2a3a5c', 1.8));
    scene.add(new THREE.HemisphereLight('#4a6a9c', '#0d1525', 1.0));
    const dirLight = new THREE.DirectionalLight('#d4e0f0', 2.6);
    dirLight.position.set(5, 3, 8); dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 512; dirLight.shadow.mapSize.height = 512;
    scene.add(dirLight);

    const pointLight = new THREE.PointLight('#e8d5a0', 16, 12, 2);
    pointLight.position.set(0, 0.2, 3.8); pointLight.castShadow = true;
    scene.add(pointLight);

    const bottomLight = new THREE.PointLight('#3a5a90', 5, 7, 2);
    bottomLight.position.set(0, -2.8, 1.2);
    scene.add(bottomLight);

    function createBaseTalismanTexture() {
      const W = 210; const H = 350;
      const texCanvas = document.createElement('canvas');
      texCanvas.width = W; texCanvas.height = H;
      const ctx = texCanvas.getContext('2d');

      const bgGrad = ctx.createLinearGradient(0, 0, W*0.8, H);
      bgGrad.addColorStop(0, '#1a3555'); bgGrad.addColorStop(0.3, '#1e3d62'); bgGrad.addColorStop(0.5, '#1b3860'); bgGrad.addColorStop(0.7, '#1a3458'); bgGrad.addColorStop(1, '#162d4e');
      ctx.fillStyle = bgGrad; ctx.fillRect(0, 0, W, H);

      ctx.globalAlpha = 0.1;
      for (let i = 0; i < 800; i++) { ctx.fillStyle = Math.random() < 0.5 ? '#d0d8e8' : '#0a1525'; ctx.fillRect(Math.random() * W, Math.random() * H, Math.random() * 3 + 0.5, Math.random() * 0.6 + 0.2); }
      ctx.globalAlpha = 0.2;
      for (let i = 0; i < 300; i++) { ctx.fillStyle = '#0a1018'; ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() < 0.5 ? Math.random() * 10 : H - Math.random() * 10, Math.random() * 2 + 0.5, 0, Math.PI*2); ctx.fill(); }
      ctx.globalAlpha = 1;

      const bm = 11; const bx = bm, by = bm, bw = W - bm*2, bh = H - bm*2;
      ctx.strokeStyle = '#8b6b4a'; ctx.lineWidth = 1; ctx.strokeRect(bx-2, by-2, bw+4, bh+4);
      ctx.strokeStyle = '#c4a265'; ctx.lineWidth = 1.5; ctx.strokeRect(bx, by, bw, bh);
      ctx.strokeStyle = '#7d5c3a'; ctx.lineWidth = 0.5; ctx.strokeRect(bx+4, by+4, bw-8, bh-8);

      const starCY = H * 0.1; const starCX = W/2; const outR = 26, inR = 10.5; const points = [];
      for (let i = 0; i < 5; i++) { const ao = -Math.PI/2 + (i * Math.PI*2)/5; const ai = -Math.PI/2 + Math.PI/5 + (i * Math.PI*2)/5; points.push({x: starCX + Math.cos(ao)*outR, y: starCY + Math.sin(ao)*outR}); points.push({x: starCX + Math.cos(ai)*inR, y: starCY + Math.sin(ai)*inR}); }
      ctx.fillStyle = 'rgba(240,200,130,0.45)'; ctx.beginPath(); ctx.moveTo(points[0].x, points[0].y); for (let i = 1; i < points.length; i++) ctx.lineTo(points[i].x, points[i].y); ctx.closePath(); ctx.fill(); ctx.strokeStyle = '#e8c870'; ctx.lineWidth = 2; ctx.shadowColor = 'rgba(255,200,100,0.7)'; ctx.shadowBlur = 8; ctx.stroke(); ctx.shadowBlur = 0;

      const yyCY = H * 0.9; const yyCX = W/2; const yyR = 21;
      ctx.fillStyle = '#e8e0d0'; ctx.strokeStyle = '#b89a60'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(yyCX, yyCY, yyR, 0, Math.PI*2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#1a3050'; ctx.beginPath(); ctx.arc(yyCX, yyCY, yyR, -Math.PI/2, Math.PI/2); ctx.fill(); ctx.fillStyle = '#e8e0d0'; ctx.beginPath(); ctx.arc(yyCX, yyCY - yyR/2, yyR/2, -Math.PI/2, Math.PI/2); ctx.fill(); ctx.fillStyle = '#1a3050'; ctx.beginPath(); ctx.arc(yyCX, yyCY + yyR/2, yyR/2, Math.PI/2, -Math.PI/2); ctx.fill();
      const eyeR = yyR/5.5; ctx.fillStyle = '#1a3050'; ctx.beginPath(); ctx.arc(yyCX, yyCY - yyR/2, eyeR, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(yyCX, yyCY - yyR/2, eyeR*0.35, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = '#e8e0d0'; ctx.beginPath(); ctx.arc(yyCX, yyCY + yyR/2, eyeR, 0, Math.PI*2); ctx.fill(); ctx.fillStyle = '#0d1520'; ctx.beginPath(); ctx.arc(yyCX, yyCY + yyR/2, eyeR*0.35, 0, Math.PI*2); ctx.fill();

      const runeStartY = by + 25; const runeEndY = by + bh - 25; const numRunes = 8; const runeSpacing = (runeEndY - runeStartY) / (numRunes - 1); const leftX = bx + 8; const rightX = bx + bw - 8;
      const drawRune = (cx, cy, s, type) => {
        ctx.save(); ctx.translate(cx, cy); ctx.strokeStyle = '#b89450'; ctx.lineWidth = 1; ctx.fillStyle = '#c4a060'; ctx.lineCap = 'round';
        if (type === 0) { ctx.beginPath(); ctx.moveTo(-s*0.6, s*0.7); ctx.quadraticCurveTo(-s*0.7, -s*0.3, 0, -s*0.65); ctx.quadraticCurveTo(s*0.7, -s*0.3, s*0.5, s*0.2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(0, -s*0.65); ctx.lineTo(0, s*0.55); ctx.stroke(); ctx.beginPath(); ctx.arc(0, s*0.55, s*0.12, 0, Math.PI*2); ctx.fill(); }
        else if (type === 1) { ctx.beginPath(); ctx.moveTo(-s*0.5, -s*0.6); ctx.lineTo(s*0.3, -s*0.15); ctx.lineTo(-s*0.25, s*0.1); ctx.lineTo(s*0.45, s*0.55); ctx.stroke(); }
        else { for (let r = -1; r <= 1; r++) { ctx.beginPath(); ctx.moveTo(-s*0.55, r*s*0.28); ctx.lineTo(s*0.55, r*s*0.28); ctx.stroke(); } ctx.beginPath(); ctx.moveTo(0, -s*0.6); ctx.lineTo(0, s*0.6); ctx.stroke(); ctx.beginPath(); ctx.arc(0, -s*0.6, s*0.1, 0, Math.PI*2); ctx.fill(); }
        ctx.restore();
      };
      for (let side = 0; side < 2; side++) { const rx = side === 0 ? leftX : rightX; for (let i = 0; i < numRunes; i++) drawRune(rx, runeStartY + i * runeSpacing, 8, (i + side) % 3); }
      return texCanvas;
    }

    const baseCanvas = createBaseTalismanTexture();
    const drawCanvas = document.createElement('canvas');
    drawCanvas.width = baseCanvas.width; drawCanvas.height = baseCanvas.height;
    const drawCtx = drawCanvas.getContext('2d');
    drawCtx.drawImage(baseCanvas, 0, 0);

    const dynamicTexture = new THREE.CanvasTexture(drawCanvas);
    dynamicTexture.colorSpace = THREE.SRGBColorSpace;
    dynamicTexture.minFilter = THREE.LinearMipmapLinearFilter;
    dynamicTexture.magFilter = THREE.LinearFilter;
    dynamicTexture.generateMipmaps = true;

    const talismanWidth = 2.0; const talismanHeight = 3.333;
    const talismanGeom = new THREE.PlaneGeometry(talismanWidth, talismanHeight, 20, 32);
    const originalPositions = new Float32Array(talismanGeom.attributes.position.array);

    const talismanMesh = new THREE.Mesh(talismanGeom, new THREE.MeshStandardMaterial({
        map: dynamicTexture, side: THREE.DoubleSide, roughness: 0.65, metalness: 0.05,
        bumpScale: 0.01, color: new THREE.Color('#ffffff'), transparent: true
    }));
    talismanMesh.castShadow = true; talismanMesh.receiveShadow = true;
    scene.add(talismanMesh);

    function createGlowTexture(inner, outer, size) {
      const c = document.createElement('canvas'); c.width = size; c.height = size; const ctx = c.getContext('2d');
      const g = ctx.createRadialGradient(size/2, size/2, 0, size/2, size/2, size/2);
      g.addColorStop(0, inner); g.addColorStop(0.25, inner); g.addColorStop(0.6, outer); g.addColorStop(1, 'transparent');
      ctx.fillStyle = g; ctx.fillRect(0, 0, size, size); return new THREE.CanvasTexture(c);
    }

    // 原有的蓝光环境粒子
    const particleCount = 40; const particleGeo = new THREE.BufferGeometry(); const particlePos = new Float32Array(particleCount * 3); const particleData = [];
    for (let i = 0; i < particleCount; i++) {
      const p = { baseX: (Math.random() - 0.5) * 2.4, baseY: -2.0 + Math.random() * 4.0, baseZ: (Math.random() - 0.5) * 1.0, speedY: Math.random() * 0.35 + 0.08, speedX: (Math.random() - 0.5) * 0.2, speedZ: (Math.random() - 0.5) * 0.2, amp: Math.random() * 0.4 + 0.2, freq: Math.random() * 1.8 + 0.6, phase: Math.random() * Math.PI * 2, life: Math.random() };
      particleData.push(p); particlePos[i*3] = p.baseX; particlePos[i*3+1] = p.baseY; particlePos[i*3+2] = p.baseZ;
    }
    particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePos, 3));
    const particles = new THREE.Points(particleGeo, new THREE.PointsMaterial({ map: createGlowTexture('#a0d0ff', '#2a5a9c', 32), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.6, color: '#7ab8e8', size: 0.15, sizeAttenuation: true }));
    scene.add(particles);

    // 灵力注入法阵的 3D 粒子系统
    const spCount = 800;
    const spGeo = new THREE.BufferGeometry();
    const spPos = new Float32Array(spCount * 3);
    const spData = [];
    for (let i = 0; i < spCount; i++) {
        spPos[i*3] = 0; spPos[i*3+1] = -100; spPos[i*3+2] = 0; // 初始隐藏在远方
        spData.push({ active: false, x:0, y:0, z:0, vx:0, vy:0, vz:0, life:0 });
    }
    spGeo.setAttribute('position', new THREE.BufferAttribute(spPos, 3));
    const spMat = new THREE.PointsMaterial({
        map: createGlowTexture('#ffffff', '#f0d060', 32),
        blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
        color: '#ffcc00', size: 0.18, sizeAttenuation: true
    });
    const spPoints = new THREE.Points(spGeo, spMat);
    scene.add(spPoints);

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();
    let isDrawing = false; let lastUV = null;
    const tempVec = new THREE.Vector3();

    let drawDistance = 0;

    function screenToUV(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      mouse.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouse, camera);
      const intersects = raycaster.intersectObject(talismanMesh);
      if (intersects.length > 0) {
        talismanMesh.worldToLocal(tempVec.copy(intersects[0].point));
        return { u: (tempVec.x / talismanWidth) + 0.5, v: 1 - ((tempVec.y / talismanHeight) + 0.5) };
      }
      return null;
    }

    function startDraw(clientX, clientY) {
      if (window.isSummoning || isBurning) return;

      const uv = screenToUV(clientX, clientY);
      if (uv && uv.u >= 0 && uv.u <= 1 && uv.v >= 0 && uv.v <= 1) {
        isDrawing = true; lastUV = uv;
        drawCtx.fillStyle = '#e8c870'; drawCtx.beginPath(); drawCtx.arc(uv.u * drawCanvas.width, uv.v * drawCanvas.height, 2.5, 0, Math.PI*2); drawCtx.fill();
        dynamicTexture.needsUpdate = true;
      }
    }

    function moveDraw(clientX, clientY) {
      if (!isDrawing || window.isSummoning || isBurning) return;
      const uv = screenToUV(clientX, clientY);
      if (uv && lastUV) {
        const dx = uv.u - lastUV.u; const dy = uv.v - lastUV.v;
        drawDistance += Math.sqrt(dx*dx + dy*dy);

        drawCtx.strokeStyle = '#e8c870'; drawCtx.lineWidth = 3.5; drawCtx.lineCap = 'round'; drawCtx.lineJoin = 'round'; drawCtx.shadowColor = 'rgba(255,200,100,0.7)'; drawCtx.shadowBlur = 6;
        drawCtx.beginPath(); drawCtx.moveTo(lastUV.u * drawCanvas.width, lastUV.v * drawCanvas.height); drawCtx.lineTo(uv.u * drawCanvas.width, uv.v * drawCanvas.height); drawCtx.stroke(); drawCtx.shadowBlur = 0;
        dynamicTexture.needsUpdate = true; lastUV = uv;
      }
    }

    function endDraw() {
      if (!isDrawing) return;
      isDrawing = false; lastUV = null;

      if (drawDistance > 0.3) {
        const infoEl = document.getElementById('drawInfo');
        infoEl.textContent = "急急如律令！";
        infoEl.style.opacity = '1';

        document.getElementById('scene3D').classList.add('berserk');

        // 备份最终画好的完整符咒，用于燃烧动画逐帧擦除
        finalTalismanCanvas = document.createElement('canvas');
        finalTalismanCanvas.width = drawCanvas.width;
        finalTalismanCanvas.height = drawCanvas.height;
        finalTalismanCanvas.getContext('2d').drawImage(drawCanvas, 0, 0);

        // 启动燃烧溶解动画
        isBurning = true;
        burnProgress = 0;

      } else {
        drawDistance = 0;
      }
    }

    window.clearTalisman = function() {
        drawCtx.globalCompositeOperation = 'source-over';
        drawCtx.clearRect(0, 0, drawCanvas.width, drawCanvas.height);
        drawCtx.drawImage(baseCanvas, 0, 0);
        dynamicTexture.needsUpdate = true;
        drawDistance = 0;
        isBurning = false;
        burnProgress = 0;
        document.getElementById('scene3D').classList.remove('berserk');
        talismanMesh.visible = true; // 恢复显示

        // 隐藏所有灵力粒子
        for(let i = 0; i < spCount; i++) {
            spData[i].active = false;
            spPos[i*3+1] = -100;
        }
        spGeo.attributes.position.needsUpdate = true;
    };

    canvas.addEventListener('mousedown', (e) => { e.preventDefault(); startDraw(e.clientX, e.clientY); });
    window.addEventListener('mousemove', (e) => { moveDraw(e.clientX, e.clientY); });
    window.addEventListener('mouseup', () => { endDraw(); });
    canvas.addEventListener('touchstart', (e) => { e.preventDefault(); if(e.touches[0]) startDraw(e.touches[0].clientX, e.touches[0].clientY); }, { passive: false });
    canvas.addEventListener('touchmove', (e) => { e.preventDefault(); if(e.touches[0]) moveDraw(e.touches[0].clientX, e.touches[0].clientY); }, { passive: false });
    canvas.addEventListener('touchend', (e) => { e.preventDefault(); endDraw(); });
    canvas.addEventListener('touchcancel', (e) => { e.preventDefault(); endDraw(); });

    const mouseInfluence = { x: 0, y: 0, targetX: 0, targetY: 0 };
    container.addEventListener('mousemove', (e) => {
      const rect = container.getBoundingClientRect();
      mouseInfluence.targetX = ((e.clientX - rect.left) / rect.width - 0.5) * 2;
      mouseInfluence.targetY = -((e.clientY - rect.top) / rect.height - 0.5) * 2;
    });

    const clock = new THREE.Clock(); let time = 0;
    function animate() {
      requestAnimationFrame(animate);
      const dt = Math.min(clock.getDelta(), 0.1); time += dt;
      mouseInfluence.x += (mouseInfluence.targetX - mouseInfluence.x) * 3.5 * dt;
      mouseInfluence.y += (mouseInfluence.targetY - mouseInfluence.y) * 3.5 * dt;

      const pos = talismanGeom.attributes.position.array;
      for (let i = 0; i < pos.length / 3; i++) {
        const ox = originalPositions[i*3]; const oy = originalPositions[i*3+1];
        const wave1 = Math.sin(oy * 1.8 - time * 1.4 + ox * 0.7) * 0.12; const wave2 = Math.sin(oy * 3.2 - time * 2.1 - ox * 1.1) * 0.05; const wave3 = Math.cos(ox * 2.5 - time * 1.0 + oy * 0.5) * 0.06;
        pos[i*3+2] = (wave1 + wave2 + wave3) * (1.0 + Math.abs(oy / 2.5) * 1.2) + (ox * mouseInfluence.x + oy * mouseInfluence.y) * 0.02;
      }
      talismanGeom.attributes.position.needsUpdate = true; talismanGeom.computeVertexNormals();
      talismanMesh.rotation.y = Math.sin(time * 0.4) * 0.06 + mouseInfluence.x * 0.03; talismanMesh.rotation.x = Math.cos(time * 0.35) * 0.04 + mouseInfluence.y * 0.02; talismanMesh.rotation.z = Math.sin(time * 0.5) * 0.03; talismanMesh.position.y = Math.sin(time * 0.55) * 0.08;

      // 燃烧与灵力粒子逻辑
      if (isBurning) {
          burnProgress += dt * 0.7; // 控制燃烧速度
          if (burnProgress >= 1.0) {
              isBurning = false;
              burnProgress = 1.0;
              talismanMesh.visible = false; // 烧完隐藏符咒

              const infoEl = document.getElementById('drawInfo');
              infoEl.textContent = "✧ 绘符以倾注灵力 ✧";
              infoEl.style.opacity = '';

              // 燃烧彻底结束后，才触发真正的召唤请求
              if (typeof window.executeSummon === 'function') {
                  window.executeSummon();
              }
          } else {
              const W = drawCanvas.width;
              const H = drawCanvas.height;
              const burnY = H * (1 - burnProgress);
              const burnHeight = 60; // 燃烧过渡带的高度

              // 1. 恢复底图
              drawCtx.globalCompositeOperation = 'source-over';
              drawCtx.clearRect(0, 0, W, H);
              drawCtx.drawImage(finalTalismanCanvas, 0, 0);

              // 2. 使用 destination-out 擦除燃烧线以下的部分，使其完全透明透出法阵
              drawCtx.globalCompositeOperation = 'destination-out';
              drawCtx.fillRect(0, burnY, W, H - burnY);

              // 3. 在燃烧边缘制造半透明溶解渐变
              const grad = drawCtx.createLinearGradient(0, burnY - burnHeight, 0, burnY);
              grad.addColorStop(0, 'rgba(0,0,0,0)');
              grad.addColorStop(1, 'rgba(0,0,0,1)');
              drawCtx.fillStyle = grad;
              drawCtx.fillRect(0, burnY - burnHeight, W, burnHeight);

              // 4. 绘制剧烈燃烧的红莲火花
              drawCtx.globalCompositeOperation = 'source-over';
              for(let i = 0; i < 80; i++) {
                  drawCtx.fillStyle = Math.random() > 0.4 ? '#ff5500' : (Math.random() > 0.5 ? '#ffcc00' : '#ff0000');
                  drawCtx.beginPath();
                  drawCtx.arc(Math.random() * W, burnY - Math.random() * burnHeight * 0.8, Math.random() * 3 + 1, 0, Math.PI * 2);
                  drawCtx.fill();
              }
              dynamicTexture.needsUpdate = true;

              // 5. 在 3D 空间中释放金色的灵力粒子飞向法阵深处
              const current3DY = -1.666 + burnProgress * 3.333; // 符咒模型的Y范围大致是 -1.666 到 1.666
              const meshY = talismanMesh.position.y;
              const worldY = current3DY + meshY;

              let spawned = 0;
              for(let i = 0; i < spCount && spawned < 20; i++) {
                  if (!spData[i].active) {
                      spData[i].active = true;
                      // 粒子从燃烧线随机剥离
                      spData[i].x = (Math.random() - 0.5) * talismanWidth + talismanMesh.position.x;
                      spData[i].y = worldY + (Math.random() - 0.5) * 0.2;
                      spData[i].z = talismanMesh.position.z + 0.05;

                      // 计算飞向法阵中心 (深处) 的速度向量
                      const tx = 0, ty = 0, tz = -3;
                      const dx = tx - spData[i].x;
                      const dy = ty - spData[i].y;
                      const dz = tz - spData[i].z;
                      const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
                      const speed = 3.0 + Math.random() * 3.0;

                      spData[i].vx = (dx / dist) * speed + (Math.random() - 0.5) * 2.0;
                      spData[i].vy = (dy / dist) * speed + (Math.random() - 0.5) * 2.0;
                      spData[i].vz = (dz / dist) * speed; // 深入 Z 轴
                      spData[i].life = 1.0;
                      spawned++;
                  }
              }
          }
      }

      // 灵力粒子物理更新
      for(let i = 0; i < spCount; i++) {
          if (spData[i].active) {
              spData[i].x += spData[i].vx * dt;
              spData[i].y += spData[i].vy * dt;
              spData[i].z += spData[i].vz * dt;
              spData[i].life -= dt * 1.2;

              // 增加一点向法阵中心的螺旋吸力
              spData[i].vx += (0 - spData[i].x) * dt * 3.0;
              spData[i].vy += (0 - spData[i].y) * dt * 3.0;

              if (spData[i].life <= 0 || spData[i].z < -6) {
                  spData[i].active = false;
                  spPos[i*3+1] = -100; // 飞入深渊后隐藏
              } else {
                  spPos[i*3] = spData[i].x;
                  spPos[i*3+1] = spData[i].y;
                  spPos[i*3+2] = spData[i].z;
              }
          }
      }
      spGeo.attributes.position.needsUpdate = true;

      const pArr = particleGeo.attributes.position.array;
      for (let i = 0; i < particleCount; i++) {
        const pd = particleData[i]; pd.life += pd.speedY * dt * 0.25;
        if (pd.life > 1.0) { pd.life -= 1.0; pd.baseX = (Math.random() - 0.5) * 2.4; pd.baseY = -2.0; pd.baseZ = (Math.random() - 0.5) * 1.0; }
        pArr[i*3] = pd.baseX + Math.sin(pd.life * pd.freq * 3 + pd.phase) * pd.amp + pd.speedX * pd.life * 2;
        pArr[i*3+1] = pd.baseY + pd.life * 4.0;
        pArr[i*3+2] = pd.baseZ + Math.cos(pd.life * pd.freq * 2.5 + pd.phase + 1) * pd.amp * 0.7 + pd.speedZ * pd.life * 2;
      }
      particleGeo.attributes.position.needsUpdate = true; pointLight.intensity = 14 + Math.sin(time * 0.8) * 2;
      renderer.render(scene, camera);
    }

    const resizeObserver = new ResizeObserver(entries => {
