    /* ==========================================
       核心抽取逻辑：根据设定概率随机分配稀有度
       ========================================== */
    function rollRarity(cfg) {
        let rand = Math.random() * 100;
        if (rand < cfg.probSSR) return 'SSR';
        rand -= cfg.probSSR;
        if (rand < cfg.probSR) return 'SR';
        rand -= cfg.probSR;
        if (rand < cfg.probR) return 'R';
        return 'N';
    }

    /* 动态获取系统提示词（已重写，去除游戏性词汇） */
    function getSystemPrompt(mode) {
        const baseFormat = `必须且只能输出一个合法的JSON数组，绝对禁止包含任何markdown标记(\`\`\`json)、前缀、注释或其他对话内容。
结构示例：[{"name":"式神名","rarity":"SSR","gender":"男/女/未知","race":"妖/神/鬼","desc":"背景故事","appearance":"外貌特征","skills":[{"name":"法术名称","desc":"法术描述"}]}]`;

        if (mode === 'game') {
            return `你是一个仅输出JSON的API。请从【阴阳师手游中已有的经典角色】中挑选，生成指定的式神数据。
请尽量用符合该世界观的叙事语言描述他们的背景、外貌和能力，不要使用过于出戏的游戏数值词汇。
` + baseFormat;
        } else {
            return `你是一个仅输出JSON的API。请以一个【独立的奇幻妖灵世界】为背景，设计全新且独一无二的式神数据。绝对不要生成手游中已经存在的角色！
请用符合该世界观的绝美叙事语言描述他们的背景、外貌和能力。绝对不要使用任何游戏性词汇（如“普攻”、“冷却”、“百分比伤害”、“回合”等），请将他们的能力描述为真实的法术、诅咒或生存本能。
` + baseFormat;
        }
    }

    /* 【修改】接收已存在的式神列表 uniqueExisting，并在 userPrompt 中加以严厉限制 */
    async function doSummonRequest(cfg, count, rarityList, uniqueExisting) {
        if (typeof window.generateRaw !== 'function') throw new Error("当前环境不支持 generateRaw");

        const systemPrompt = getSystemPrompt(cfg.summonMode);

        // 如果存在已拥有的式神，则在提示词中加上极其严格的限制
        let avoidPrompt = '';
        if (uniqueExisting && uniqueExisting.length > 0) {
            avoidPrompt = `\n\n【极度重要】召唤者的式神录中已经存在以下式神，绝对禁止生成列表中存在的任何式神（名字绝对不能重复）：\n${uniqueExisting.join(', ')}`;
        }

        const userPrompt = `请严格按照格式要求，生成 ${count} 个式神数据的JSON数组。
本次召唤的命运指引（稀有度分配）如下：${rarityList.join(', ')}。
请确保生成的每个式神严格对应上述稀有度，并填入 JSON 的 rarity 字段中。${avoidPrompt}`;

        const payload = {
            user_input: userPrompt,
            ordered_prompts: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt } ]
        };
        if (cfg.mode === 'external') {
            payload.custom_api = { apiurl: cfg.url, key: cfg.key, model: cfg.model, source: 'openai', max_tokens: parseInt(cfg.maxTokens) || 4000 };
        }
        return await window.generateRaw(payload);
    }

    window.executeSummon = async function() {
        if (window.isSummoning) return;
        const count = currentSummonCount; const cfg = saveConfigSilent();

        await refreshAmuletCount();
        if (currentAmulets < count) { window.clearTalisman(); return showMsg(`灵力不足！当前仅有 ${currentAmulets} 张符咒。`, "error"); }
        if (cfg.mode === 'external' && (!cfg.url || !cfg.model)) { window.clearTalisman(); showMsg("请先配置魔力源！", "error"); $('settingsModalBg').classList.add('active'); return; }

        window.isSummoning = true;
        $('btnMinus').disabled = true; $('btnPlus').disabled = true;
        $('resultArea').innerHTML = ''; $('resultOverlay').classList.remove('active');
        $('ssrFlash').classList.remove('active');
        showMsg(`符咒召唤中...`, "loading");

        if (!(await deductAmulet(count))) {
            window.isSummoning = false; updateCountDisplay(); window.clearTalisman();
            return showMsg("扣除符咒失败", "error");
        }

        try {
            // 【新增】神识扫锚：提取哥哥目前已经拥有的式神名字，防止重复
            const data = getSafeMvuData();
            const roster = data.stat_data['式神录'] || {};
            // 处理同名式神带 "_1" 的情况，只提取真实名字
            const existingShikis = Object.keys(roster).map(k => k.split('_')[0]);
            const uniqueExisting = [...new Set(existingShikis)];

            // 提前算好这次十连的稀有度
            let rarityList = [];
            for (let i = 0; i < count; i++) {
                rarityList.push(rollRarity(cfg));
            }

            // 【修改】将 uniqueExisting 传给请求函数
            let rawText = await doSummonRequest(cfg, count, rarityList, uniqueExisting);
            let cleanStr = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

            let startIdx = cleanStr.indexOf('['); let endIdx = cleanStr.lastIndexOf(']');
            if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) { cleanStr = cleanStr.substring(startIdx, endIdx + 1); }
            else if (startIdx !== -1) { cleanStr = cleanStr.substring(startIdx); }
            else { let objStart = cleanStr.indexOf('{'); let objEnd = cleanStr.lastIndexOf('}'); if (objStart !== -1 && objEnd !== -1) { cleanStr = '[' + cleanStr.substring(objStart, objEnd + 1) + ']'; } }

            let parsed;
            try { parsed = JSON.parse(cleanStr); } catch (parseError) {
                console.error("【式神召唤】JSON 解析失败！\n原始返回：", rawText);
                throw new Error("妖气干扰，数据破损。请按F12查看，或调大Max Tokens！");
            }

            if (!Array.isArray(parsed)) parsed = [parsed];
            if (parsed.length > count) parsed = parsed.slice(0, count);

            currentResults = parsed; let html = '';
            let hasHighRarity = false;

            parsed.forEach((item, idx) => {
                // 强制覆写稀有度，防止 LLM 不听话乱填
                const rarity = rarityList[idx] || item.rarity || 'R';
                item.rarity = rarity;

                if (rarity === 'SSR' || rarity === 'SP') hasHighRarity = true;

                let skillsHtml = (item.skills||[]).map(sk => `<div class="skill-item"><span class="skill-name">【${sk.name||'秘术'}】</span> ${sk.desc||''}</div>`).join('');

                html += `<div class="shikigami-card rarity-${rarity} flip-in" style="animation-delay: ${idx * 0.15 + 0.2}s">
                    <div class="card-head"><div class="card-name">${item.name || '未知魂灵'}</div><div class="card-rarity">${rarity}</div></div>
                    <div class="card-sub">${item.race||'妖'} · ${item.gender||'未知'}</div>
                    <div class="card-desc">${item.appearance||''} ${item.desc||''}</div>
                    ${skillsHtml ? `<div class="card-skills">${skillsHtml}</div>` : ''}
                    <button class="btn-bind" onclick="bindShikigami(${idx}, this)">缔结契约</button>
                </div>`;
            });

            if (hasHighRarity) {
                $('ssrFlash').classList.add('active');
            }

            $('resultArea').innerHTML = html;
            $('resultOverlay').classList.add('active');
            showMsg("契约已成！", "success");

            window.clearTalisman();
        } catch (e) {
            showMsg(`法阵干扰: ${e.message}`, "error", 6000);
            await refundAmulet(count);
            window.clearTalisman();
        } finally {
            window.isSummoning = false; updateCountDisplay();
        }
    };

    async function init() {
        loadConfig();
        if (typeof window.waitGlobalInitialized === 'function') {
            await window.waitGlobalInitialized('Mvu'); await refreshAmuletCount();
        } else {
            $('amuletCount').textContent = "异常"; showMsg("未检测到MVU框架", "error");
        }
        updateCountDisplay();
    }
    init();
</script>
</body>
</html>
